INSERT INTO sat_questions (question_id, external_id, vault_id, disclosed_item_id, source, program, test_type, test_type_desc, domain, primary_class_cd, skill_cd, skill_desc, difficulty, score_band_range_cd, question_type, stimulus_html, stem_html, answer_options, correct_answer, answer_keys, rationale_html, correct_answer_extracted_from_rationale, image_count, parent_template_name, parent_template_id, template_cluster_id, template_cluster_name, origin, position, answer_style, section, raw_payload, created_date, updated_date) VALUES
    ($SATQ$a0777403$SATQ$, $SATQ$602f691b-2659-4652-bb76-ca61180145b9$SATQ$::uuid, NULL, NULL, $SATQ$qbank$SATQ$, $SATQ$SAT$SATQ$, 1, $SATQ$Reading and Writing$SATQ$, $SATQ$Craft and Structure$SATQ$, $SATQ$CAS$SATQ$, $SATQ$WIC$SATQ$, $SATQ$Words in Context$SATQ$, $SATQ$E$SATQ$, 1, $SATQ$mcq$SATQ$, $SATQ$<p>The following text is from Anita Desai&rsquo;s 2011 novella <em>Translator Translated</em>. While working on her translation of a novel written in Odia (a language of India) into English, the narrator looks out her window at night to clear her mind.</p>
<blockquote>
<p>I tried to distract myself with these sights of the ordinary world, but in my mind it was the lines I had been translating and the lines that I had been writing that remained in the forefront. I longed for sleep to obliterate them but it eluded me. Perhaps everything would be normal again once I had sent off the manuscript, I thought, and looked forward to <span style="text-decoration: underline;" role="region" aria-label="Referenced Content">completing</span> the work.</p>
</blockquote>
<p style="text-align: right;"><span class="dap_copyright">&copy;2011 by Anita Desai</span></p>$SATQ$, $SATQ$<p>As used in the text, what does the word &ldquo;completing&rdquo; most nearly mean?</p>$SATQ$, $SATQ$[{"id":"20ad9946-c36c-4be9-906c-876c510d9b30","content":"<p>Destroying</p>"},{"id":"5fe555e7-7f68-480b-8487-b50006542ce2","content":"<p>Finishing</p>"},{"id":"3aefd23e-28e5-434e-b935-4ae2c42f7270","content":"<p>Advertising</p>"},{"id":"8f6ada64-253c-48a0-9abc-01ca69b5a20d","content":"<p>Rejecting</p>"}]$SATQ$::jsonb, $SATQ$["B"]$SATQ$::jsonb, $SATQ$["5fe555e7-7f68-480b-8487-b50006542ce2"]$SATQ$::jsonb, $SATQ$<p>Choice B is the best answer because as used in the text, "completing" most nearly means finishing. In the text, the narrator conveys that the task of translating a novel has been an all-consuming one and that she hopes things will "be normal again" once she has "sent off the manuscript." In other words, the narrator is looking forward to finishing her work on the manuscript and returning to other things.</p><p>Choice A is incorrect because in this context, "completing" doesn&rsquo;t mean destroying, or ruining. The narrator addresses her desire to send off the manuscript she&rsquo;s focused on and her hope that things will be "normal again" once she does, conveying that she is looking forward to finishing the work, not to ruining it. Choice C is incorrect because in this context, "completing" doesn&rsquo;t mean advertising, or publicly promoting. The narrator addresses her complete focus on the translation and her hope that things will be "normal again" once she has "sent off the manuscript," conveying that she is looking forward to finishing the task, not to promoting the resulting manuscript. Choice D is incorrect because in this context, "completing" doesn&rsquo;t mean rejecting, or refusing or repelling. The narrator makes it clear that she is absorbed in working on the translation and plans to send off the manuscript, suggesting that instead of refusing to do the work, she is continuing to do it (even if she looks forward to things being "normal again" when she&rsquo;s done).</p>$SATQ$, false, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, $SATQ${"questionId":"a0777403","external_id":"602f691b-2659-4652-bb76-ca61180145b9","vaultid":null,"uId":"0d9fb460-1324-401f-b54b-df21872d806f","program":"SAT","test_type":1,"test_type_desc":"Reading and Writing","primary_class_cd":"CAS","domain":"Craft and Structure","skill_cd":"WIC","skill_desc":"Words in Context","difficulty":"E","score_band_range_cd":1,"type":"mcq","stimulus":"<p>The following text is from Anita Desai&rsquo;s 2011 novella <em>Translator Translated</em>. While working on her translation of a novel written in Odia (a language of India) into English, the narrator looks out her window at night to clear her mind.</p>\n<blockquote>\n<p>I tried to distract myself with these sights of the ordinary world, but in my mind it was the lines I had been translating and the lines that I had been writing that remained in the forefront. I longed for sleep to obliterate them but it eluded me. Perhaps everything would be normal again once I had sent off the manuscript, I thought, and looked forward to <span style=\"text-decoration: underline;\" role=\"region\" aria-label=\"Referenced Content\">completing</span> the work.</p>\n</blockquote>\n<p style=\"text-align: right;\"><span class=\"dap_copyright\">&copy;2011 by Anita Desai</span></p>","stem":"<p>As used in the text, what does the word &ldquo;completing&rdquo; most nearly mean?</p>","answerOptions":[{"id":"20ad9946-c36c-4be9-906c-876c510d9b30","content":"<p>Destroying</p>"},{"id":"5fe555e7-7f68-480b-8487-b50006542ce2","content":"<p>Finishing</p>"},{"id":"3aefd23e-28e5-434e-b935-4ae2c42f7270","content":"<p>Advertising</p>"},{"id":"8f6ada64-253c-48a0-9abc-01ca69b5a20d","content":"<p>Rejecting</p>"}],"keys":["5fe555e7-7f68-480b-8487-b50006542ce2"],"correct_answer":["B"],"rationale":"<p>Choice B is the best answer because as used in the text, \"completing\" most nearly means finishing. In the text, the narrator conveys that the task of translating a novel has been an all-consuming one and that she hopes things will \"be normal again\" once she has \"sent off the manuscript.\" In other words, the narrator is looking forward to finishing her work on the manuscript and returning to other things.</p><p>Choice A is incorrect because in this context, \"completing\" doesn&rsquo;t mean destroying, or ruining. The narrator addresses her desire to send off the manuscript she&rsquo;s focused on and her hope that things will be \"normal again\" once she does, conveying that she is looking forward to finishing the work, not to ruining it. Choice C is incorrect because in this context, \"completing\" doesn&rsquo;t mean advertising, or publicly promoting. The narrator addresses her complete focus on the translation and her hope that things will be \"normal again\" once she has \"sent off the manuscript,\" conveying that she is looking forward to finishing the task, not to promoting the resulting manuscript. Choice D is incorrect because in this context, \"completing\" doesn&rsquo;t mean rejecting, or refusing or repelling. The narrator makes it clear that she is absorbed in working on the translation and plans to send off the manuscript, suggesting that instead of refusing to do the work, she is continuing to do it (even if she looks forward to things being \"normal again\" when she&rsquo;s done).</p>","parenttemplatename":null,"parenttemplateid":null,"templateclusterid":null,"templateclustername":null,"origin":null,"position":null,"createDate":1743430669208,"updateDate":1743430669208}$SATQ$::jsonb, 1743430669208, 1743430669208),
    ($SATQ$a086c2cb$SATQ$, $SATQ$931c68e8-c59b-4d75-8c98-213ba5557018$SATQ$::uuid, NULL, NULL, $SATQ$qbank$SATQ$, $SATQ$SAT$SATQ$, 1, $SATQ$Reading and Writing$SATQ$, $SATQ$Craft and Structure$SATQ$, $SATQ$CAS$SATQ$, $SATQ$TSP$SATQ$, $SATQ$Text Structure and Purpose$SATQ$, $SATQ$E$SATQ$, 3, $SATQ$mcq$SATQ$, $SATQ$<p>Built in the 1970s, Raccoon Mountain is a pumped-storage hydropower facility (a &ldquo;water-battery&rdquo;) located in the United States along the Tennessee River. When energy demand is low, excess power from the regional electric utility&rsquo;s nuclear plants is used to pump water (from a lower reservoir filled from the Tennessee River) up a shaft to the summit lake, where the water is stored as gravitational potential energy. When energy demand peaks, the water drains down from the summit lake, spinning turbines and generating upward of 1,700 megawatts of power&mdash;enough to power one million homes for twenty hours.</p>$SATQ$, $SATQ$<p>Which choice best states the main purpose of the text?</p>$SATQ$, $SATQ$[{"id":"a7564665-03fc-4d59-bfc7-08aa505e1113","content":"<p>To point out the differences between two methods of energy generation</p>"},{"id":"f6f94ad7-e997-4dbf-a685-201e47103b99","content":"<p>To explain the basics of how a specific energy technology works</p>"},{"id":"eb011c48-e81a-48db-a8ef-fd7f1ed29b57","content":"<p>To encourage regional electric utilities to build energy storage facilities</p>"},{"id":"e640dc9c-7537-4b32-add4-89d5035c2f23","content":"<p>To discuss the benefits of a new energy technology</p>"}]$SATQ$::jsonb, $SATQ$["B"]$SATQ$::jsonb, $SATQ$["f6f94ad7-e997-4dbf-a685-201e47103b99"]$SATQ$::jsonb, $SATQ$<p>Choice B is the best answer because it most accurately describes the main purpose of the text, which is to explain the basics of how a specific energy technology works. The text introduces Raccoon Mountain as a pumped-storage hydropower facility built in the 1970s and then explains how it operates: during periods of low demand, excess power pumps water up to a lake at the mountain&rsquo;s summit, and when demand for energy peaks, the water flows back down, spinning turbines along the way to generate electricity. The text provides some additional details, like the name of the water source, but the overall focus is on explaining the basics of how pumped-storage hydropower works.</p><p>Choice A is incorrect because the text focuses on one method of energy generation&mdash;pumped-water hydropower&mdash;and briefly mentions another type of energy generation (nuclear plants) only to identify it as a source of power for the pumping process. The text never makes any comparison between the two methods. Choice C is incorrect because the text simply gives a factual description of how Raccoon Mountain, a pumped-storage hydropower facility, operates; it never suggests that more energy storage facilities should be built, whether by regional utilities or by any other entity. Choice D is incorrect because the text doesn&rsquo;t present pumped-storage hydropower as a new technology; it indicates that Raccoon Mountain was built in the 1970s, meaning that, rather than being new, this facility is approximately 50 years old.</p>$SATQ$, false, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, $SATQ${"questionId":"a086c2cb","external_id":"931c68e8-c59b-4d75-8c98-213ba5557018","vaultid":null,"uId":"8e32c970-853c-4f29-ba46-85657fe798b5","program":"SAT","test_type":1,"test_type_desc":"Reading and Writing","primary_class_cd":"CAS","domain":"Craft and Structure","skill_cd":"TSP","skill_desc":"Text Structure and Purpose","difficulty":"E","score_band_range_cd":3,"type":"mcq","stimulus":"<p>Built in the 1970s, Raccoon Mountain is a pumped-storage hydropower facility (a &ldquo;water-battery&rdquo;) located in the United States along the Tennessee River. When energy demand is low, excess power from the regional electric utility&rsquo;s nuclear plants is used to pump water (from a lower reservoir filled from the Tennessee River) up a shaft to the summit lake, where the water is stored as gravitational potential energy. When energy demand peaks, the water drains down from the summit lake, spinning turbines and generating upward of 1,700 megawatts of power&mdash;enough to power one million homes for twenty hours.</p>","stem":"<p>Which choice best states the main purpose of the text?</p>","answerOptions":[{"id":"a7564665-03fc-4d59-bfc7-08aa505e1113","content":"<p>To point out the differences between two methods of energy generation</p>"},{"id":"f6f94ad7-e997-4dbf-a685-201e47103b99","content":"<p>To explain the basics of how a specific energy technology works</p>"},{"id":"eb011c48-e81a-48db-a8ef-fd7f1ed29b57","content":"<p>To encourage regional electric utilities to build energy storage facilities</p>"},{"id":"e640dc9c-7537-4b32-add4-89d5035c2f23","content":"<p>To discuss the benefits of a new energy technology</p>"}],"keys":["f6f94ad7-e997-4dbf-a685-201e47103b99"],"correct_answer":["B"],"rationale":"<p>Choice B is the best answer because it most accurately describes the main purpose of the text, which is to explain the basics of how a specific energy technology works. The text introduces Raccoon Mountain as a pumped-storage hydropower facility built in the 1970s and then explains how it operates: during periods of low demand, excess power pumps water up to a lake at the mountain&rsquo;s summit, and when demand for energy peaks, the water flows back down, spinning turbines along the way to generate electricity. The text provides some additional details, like the name of the water source, but the overall focus is on explaining the basics of how pumped-storage hydropower works.</p><p>Choice A is incorrect because the text focuses on one method of energy generation&mdash;pumped-water hydropower&mdash;and briefly mentions another type of energy generation (nuclear plants) only to identify it as a source of power for the pumping process. The text never makes any comparison between the two methods. Choice C is incorrect because the text simply gives a factual description of how Raccoon Mountain, a pumped-storage hydropower facility, operates; it never suggests that more energy storage facilities should be built, whether by regional utilities or by any other entity. Choice D is incorrect because the text doesn&rsquo;t present pumped-storage hydropower as a new technology; it indicates that Raccoon Mountain was built in the 1970s, meaning that, rather than being new, this facility is approximately 50 years old.</p>","parenttemplatename":null,"parenttemplateid":null,"templateclusterid":null,"templateclustername":null,"origin":null,"position":null,"createDate":1776362771169,"updateDate":1776362771169}$SATQ$::jsonb, 1776362771169, 1776362771169),
    ($SATQ$a1139ff8$SATQ$, $SATQ$3defff55-27df-4f13-a97e-20c0420ab51d$SATQ$::uuid, NULL, NULL, $SATQ$qbank$SATQ$, $SATQ$SAT$SATQ$, 1, $SATQ$Reading and Writing$SATQ$, $SATQ$Craft and Structure$SATQ$, $SATQ$CAS$SATQ$, $SATQ$WIC$SATQ$, $SATQ$Words in Context$SATQ$, $SATQ$E$SATQ$, 1, $SATQ$mcq$SATQ$, $SATQ$<p>In the 1990s, conservationists began planting more than 500,000 native trees in the habitat of the Azores bullfinch to boost the bird&rsquo;s numbers. This approach was apparently <span aria-hidden="true">______</span><span class="sr-only">blank</span>: the Azores bullfinch&rsquo;s population size increased from as few as 100 birds at the end of the 1980s to around 1,300 in 2023.&nbsp;</p>$SATQ$, $SATQ$<p>Which choice completes the text with the most logical and precise word or phrase?</p>$SATQ$, $SATQ$[{"id":"3d01da1c-ab3d-4edb-ae07-30277c8cabf0","content":"<p>amusing</p>"},{"id":"b14996c9-44e9-4ec7-a683-269cea99aac8","content":"<p>costly</p>"},{"id":"8f464376-9237-47d0-9674-8fa8cb94cfb0","content":"<p>successful</p>"},{"id":"8a5699b4-0eb9-4d3a-8922-2eb418e5f5dd","content":"<p>disastrous</p>"}]$SATQ$::jsonb, $SATQ$["C"]$SATQ$::jsonb, $SATQ$["8f464376-9237-47d0-9674-8fa8cb94cfb0"]$SATQ$::jsonb, $SATQ$<p>Choice C is the best answer because it most logically completes the text&rsquo;s discussion of the conservationists&rsquo; efforts to increase Azores bullfinch&rsquo;s numbers. In this context, "successful" means accomplishing a goal or purpose. According to the text, conservationists planted more than 500,000 native trees in an Azores bullfinch habitat in order to boost the bird&rsquo;s population size. The text then indicates that the population size did indeed grow as a result of the planted trees. Thus, in this context, the conservationists&rsquo; approach of planting native trees was successful because it achieved the goal of increasing the bird&rsquo;s population size.</p><p>Choice A is incorrect because the text gives no indication that the conservationists&rsquo; approach of planting native trees to increase Azores bullfinch&rsquo;s numbers was "amusing," or comical or entertaining. Instead, the approach was seriously undertaken and ultimately accomplished. Choice B is incorrect because the text doesn&rsquo;t address how much it cost to achieve the goal of planting native trees to increase Azores bullfinch&rsquo;s numbers. The text indicates that the approach was beneficial and successful rather than "costly," or expensive or harmful. Choice D is incorrect. According to the text, the conservationists&rsquo; approach of planting native trees to increase Azores bullfinch&rsquo;s numbers was beneficial and successful rather than "disastrous," or damaging or unsuccessful.</p>$SATQ$, false, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, $SATQ${"questionId":"a1139ff8","external_id":"3defff55-27df-4f13-a97e-20c0420ab51d","vaultid":null,"uId":"0ca6bc33-889c-45ef-a156-03bb91593942","program":"SAT","test_type":1,"test_type_desc":"Reading and Writing","primary_class_cd":"CAS","domain":"Craft and Structure","skill_cd":"WIC","skill_desc":"Words in Context","difficulty":"E","score_band_range_cd":1,"type":"mcq","stimulus":"<p>In the 1990s, conservationists began planting more than 500,000 native trees in the habitat of the Azores bullfinch to boost the bird&rsquo;s numbers. This approach was apparently <span aria-hidden=\"true\">______</span><span class=\"sr-only\">blank</span>: the Azores bullfinch&rsquo;s population size increased from as few as 100 birds at the end of the 1980s to around 1,300 in 2023.&nbsp;</p>","stem":"<p>Which choice completes the text with the most logical and precise word or phrase?</p>","answerOptions":[{"id":"3d01da1c-ab3d-4edb-ae07-30277c8cabf0","content":"<p>amusing</p>"},{"id":"b14996c9-44e9-4ec7-a683-269cea99aac8","content":"<p>costly</p>"},{"id":"8f464376-9237-47d0-9674-8fa8cb94cfb0","content":"<p>successful</p>"},{"id":"8a5699b4-0eb9-4d3a-8922-2eb418e5f5dd","content":"<p>disastrous</p>"}],"keys":["8f464376-9237-47d0-9674-8fa8cb94cfb0"],"correct_answer":["C"],"rationale":"<p>Choice C is the best answer because it most logically completes the text&rsquo;s discussion of the conservationists&rsquo; efforts to increase Azores bullfinch&rsquo;s numbers. In this context, \"successful\" means accomplishing a goal or purpose. According to the text, conservationists planted more than 500,000 native trees in an Azores bullfinch habitat in order to boost the bird&rsquo;s population size. The text then indicates that the population size did indeed grow as a result of the planted trees. Thus, in this context, the conservationists&rsquo; approach of planting native trees was successful because it achieved the goal of increasing the bird&rsquo;s population size.</p><p>Choice A is incorrect because the text gives no indication that the conservationists&rsquo; approach of planting native trees to increase Azores bullfinch&rsquo;s numbers was \"amusing,\" or comical or entertaining. Instead, the approach was seriously undertaken and ultimately accomplished. Choice B is incorrect because the text doesn&rsquo;t address how much it cost to achieve the goal of planting native trees to increase Azores bullfinch&rsquo;s numbers. The text indicates that the approach was beneficial and successful rather than \"costly,\" or expensive or harmful. Choice D is incorrect. According to the text, the conservationists&rsquo; approach of planting native trees to increase Azores bullfinch&rsquo;s numbers was beneficial and successful rather than \"disastrous,\" or damaging or unsuccessful.</p>","parenttemplatename":null,"parenttemplateid":null,"templateclusterid":null,"templateclustername":null,"origin":null,"position":null,"createDate":1743430669205,"updateDate":1743430669205}$SATQ$::jsonb, 1743430669205, 1743430669205),
    ($SATQ$a1d2c4d0$SATQ$, $SATQ$b7ccd3ab-1793-4b91-a1a3-9a33c8095745$SATQ$::uuid, NULL, NULL, $SATQ$qbank$SATQ$, $SATQ$SAT$SATQ$, 1, $SATQ$Reading and Writing$SATQ$, $SATQ$Craft and Structure$SATQ$, $SATQ$CAS$SATQ$, $SATQ$TSP$SATQ$, $SATQ$Text Structure and Purpose$SATQ$, $SATQ$H$SATQ$, 6, $SATQ$mcq$SATQ$, $SATQ$<p>Pteropods are small swimming snails with thin, delicate calcium carbonate shells. These animals are thought to be especially vulnerable to ocean acidification due to calcium carbonate&rsquo;s susceptibility to dissolution at lower pH values. Victoria <span data-ssml-sub-alias="L">L.</span> Peck and colleagues recently found that the periostracum (a protective coating on pteropods&rsquo; outer shells) prevents this dissolution when intact. Moreover, the team was surprised to discover that even when the periostracum is breached, pteropods can still mitigate damage by rebuilding the inner shell wall.</p>$SATQ$, $SATQ$<p>Which choice best describes the main purpose of the text?</p>$SATQ$, $SATQ$[{"id":"0783cd5b-a2ae-4367-aa48-ff395ddb5852","content":"<p>To call for additional research on biological mechanisms that improve pteropod survival rates</p>"},{"id":"3ac0506f-ccea-4f87-94a7-78271d47e068","content":"<p>To discuss a conclusion drawn in a study of calcium carbonate&rsquo;s role in protecting the periostracum of pteropods</p>"},{"id":"411b6e8d-5268-4b4a-ac2b-d78ac2cd1d8c","content":"<p>To address some of the ways ocean acidification has altered pteropod behavior over time</p>"},{"id":"48d511de-c04b-433c-a7d3-94f17d5c260c","content":"<p>To present findings that suggest that a concern about the effects of ocean acidification on pteropod shells may be unwarranted&nbsp;</p>"}]$SATQ$::jsonb, $SATQ$["D"]$SATQ$::jsonb, $SATQ$["48d511de-c04b-433c-a7d3-94f17d5c260c"]$SATQ$::jsonb, $SATQ$<p>Choice D is the best answer because it most accurately describes the main purpose of the text, which is to present findings that suggest a previously held concern about the effects of ocean acidification on pteropod shells may be unwarranted. The text introduces the concern that pteropods are thought to be particularly vulnerable to ocean acidification, or lower pH levels, due to the susceptibility of their calcium carbonate shells to dissolution at lower pH levels. However, the text then describes findings from a recent study that suggest this concern may be unjustified, insofar as the protective periostracum coating on a pteropod&rsquo;s shell prevents dissolution, and even when the coating is breached, a pteropod can rebuild the inner shell wall, reducing the damage.</p><p>Choice A is incorrect because the text doesn&rsquo;t call for additional research or suggest that more research is needed on biological mechanisms that improve pteropod survival rates. Instead, the text discusses a recent study showing that pteropods may not be as vulnerable to ocean acidification as is feared. Choice B is incorrect because the study discussed in the text doesn&rsquo;t address calcium carbonate&rsquo;s role in protecting the periostracum of pteropods. According to the text, the study addresses the periostracum&rsquo;s role in protecting pteropods&rsquo; calcium carbonate shells from dissolution due to ocean acidification. Choice C is incorrect because the text doesn&rsquo;t address how ocean acidification has altered pteropod behavior over time. Instead, the text focuses on the potential effects of ocean acidification on pteropods&rsquo; shells and the mechanisms protecting against those effects.</p>$SATQ$, false, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, $SATQ${"questionId":"a1d2c4d0","external_id":"b7ccd3ab-1793-4b91-a1a3-9a33c8095745","vaultid":null,"uId":"cffe3569-b063-48e5-8f14-b024cdd172c3","program":"SAT","test_type":1,"test_type_desc":"Reading and Writing","primary_class_cd":"CAS","domain":"Craft and Structure","skill_cd":"TSP","skill_desc":"Text Structure and Purpose","difficulty":"H","score_band_range_cd":6,"type":"mcq","stimulus":"<p>Pteropods are small swimming snails with thin, delicate calcium carbonate shells. These animals are thought to be especially vulnerable to ocean acidification due to calcium carbonate&rsquo;s susceptibility to dissolution at lower pH values. Victoria <span data-ssml-sub-alias=\"L\">L.</span> Peck and colleagues recently found that the periostracum (a protective coating on pteropods&rsquo; outer shells) prevents this dissolution when intact. Moreover, the team was surprised to discover that even when the periostracum is breached, pteropods can still mitigate damage by rebuilding the inner shell wall.</p>","stem":"<p>Which choice best describes the main purpose of the text?</p>","answerOptions":[{"id":"0783cd5b-a2ae-4367-aa48-ff395ddb5852","content":"<p>To call for additional research on biological mechanisms that improve pteropod survival rates</p>"},{"id":"3ac0506f-ccea-4f87-94a7-78271d47e068","content":"<p>To discuss a conclusion drawn in a study of calcium carbonate&rsquo;s role in protecting the periostracum of pteropods</p>"},{"id":"411b6e8d-5268-4b4a-ac2b-d78ac2cd1d8c","content":"<p>To address some of the ways ocean acidification has altered pteropod behavior over time</p>"},{"id":"48d511de-c04b-433c-a7d3-94f17d5c260c","content":"<p>To present findings that suggest that a concern about the effects of ocean acidification on pteropod shells may be unwarranted&nbsp;</p>"}],"keys":["48d511de-c04b-433c-a7d3-94f17d5c260c"],"correct_answer":["D"],"rationale":"<p>Choice D is the best answer because it most accurately describes the main purpose of the text, which is to present findings that suggest a previously held concern about the effects of ocean acidification on pteropod shells may be unwarranted. The text introduces the concern that pteropods are thought to be particularly vulnerable to ocean acidification, or lower pH levels, due to the susceptibility of their calcium carbonate shells to dissolution at lower pH levels. However, the text then describes findings from a recent study that suggest this concern may be unjustified, insofar as the protective periostracum coating on a pteropod&rsquo;s shell prevents dissolution, and even when the coating is breached, a pteropod can rebuild the inner shell wall, reducing the damage.</p><p>Choice A is incorrect because the text doesn&rsquo;t call for additional research or suggest that more research is needed on biological mechanisms that improve pteropod survival rates. Instead, the text discusses a recent study showing that pteropods may not be as vulnerable to ocean acidification as is feared. Choice B is incorrect because the study discussed in the text doesn&rsquo;t address calcium carbonate&rsquo;s role in protecting the periostracum of pteropods. According to the text, the study addresses the periostracum&rsquo;s role in protecting pteropods&rsquo; calcium carbonate shells from dissolution due to ocean acidification. Choice C is incorrect because the text doesn&rsquo;t address how ocean acidification has altered pteropod behavior over time. Instead, the text focuses on the potential effects of ocean acidification on pteropods&rsquo; shells and the mechanisms protecting against those effects.</p>","parenttemplatename":null,"parenttemplateid":null,"templateclusterid":null,"templateclustername":null,"origin":null,"position":null,"createDate":1743430669212,"updateDate":1743430669212}$SATQ$::jsonb, 1743430669212, 1743430669212),
    ($SATQ$a1ff8ce3$SATQ$, $SATQ$ca82da8c-c2b9-45b2-8f62-1aff0d7b4de2$SATQ$::uuid, NULL, NULL, $SATQ$qbank$SATQ$, $SATQ$SAT$SATQ$, 1, $SATQ$Reading and Writing$SATQ$, $SATQ$Craft and Structure$SATQ$, $SATQ$CAS$SATQ$, $SATQ$WIC$SATQ$, $SATQ$Words in Context$SATQ$, $SATQ$H$SATQ$, 6, $SATQ$mcq$SATQ$, $SATQ$<p>As discussed by scholar Anna Mladentseva, many artworks produced in the mid-1990s to the early 2000s exclusively for exhibition on the internet, such as Sinae Kim&rsquo;s <em>Genesis </em>(2001), have become inaccessible because viewing them requires the use of <span aria-hidden="true">______</span><span class="sr-only">blank</span> software (most notably Adobe Flash, discontinued in 2021).</p>$SATQ$, $SATQ$<p>Which choice completes the text with the most logical and precise word or phrase?</p>$SATQ$, $SATQ$[{"id":"00c9c035-bf32-4db7-b1d5-0e66f409c904","content":"<p>defunct</p>"},{"id":"a0f4b726-7c3a-4b19-8894-97688a491885","content":"<p>arcane</p>"},{"id":"b5ec70de-950e-4497-823f-87504d5d6159","content":"<p>ubiquitous</p>"},{"id":"1e34cd76-6b1f-46f7-b624-a91bd40183dc","content":"<p>extraneous</p>"}]$SATQ$::jsonb, $SATQ$["A"]$SATQ$::jsonb, $SATQ$["00c9c035-bf32-4db7-b1d5-0e66f409c904"]$SATQ$::jsonb, $SATQ$<p>Choice A is the best answer because it most logically completes the text&rsquo;s discussion of artworks that were produced for exhibition on the internet. In this context, "defunct" means no longer existing or functioning. According to the text, many artworks that were produced in the mid-1990s to the early 2000s for exhibition on the internet have become inaccessible due to their reliance on certain software. As an example, the text cites Sinae Kim&rsquo;s <em>Genesis</em>, which relied on software that was discontinued in 2021. This context supports the idea that the software is defunct.</p><p>Choice B is incorrect because the text indicates that viewing artworks produced in the mid-1990s to the early 2000s for exhibition on the internet requires the use of software. Artists generally want their works to be seen by many people, so it wouldn&rsquo;t make sense for creators of internet art to require the use of software that is "arcane," or known or knowable to only a few people. Moreover, the text states that a prominent example of software used to view these artworks is Adobe Flash, which was discontinued in 2021, meaning it&rsquo;s now defunct. Choice C is incorrect because "ubiquitous" would mean found everywhere, which wouldn&rsquo;t make sense in this context. The text indicates that the reason why many artworks that were produced in the mid-1990s to the early 2000s for exhibition on the internet have become inaccessible has to do with the software required for viewing them. According to the text, one example of such software is Adobe Flash, which was discontinued in 2021, meaning it&rsquo;s now defunct. Choice D is incorrect because nothing in the text suggests that the software used to view artworks produced in the mid-1990s to the early 2000s for exhibition on the internet is "extraneous," or irrelevant. Instead, the text indicates that use of specific software is required to view certain artworks from this period and that the discontinuation of the software renders the works inaccessible.</p>$SATQ$, false, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, $SATQ${"questionId":"a1ff8ce3","external_id":"ca82da8c-c2b9-45b2-8f62-1aff0d7b4de2","vaultid":null,"uId":"971cf5bb-2215-4157-af2c-fb42d05658b2","program":"SAT","test_type":1,"test_type_desc":"Reading and Writing","primary_class_cd":"CAS","domain":"Craft and Structure","skill_cd":"WIC","skill_desc":"Words in Context","difficulty":"H","score_band_range_cd":6,"type":"mcq","stimulus":"<p>As discussed by scholar Anna Mladentseva, many artworks produced in the mid-1990s to the early 2000s exclusively for exhibition on the internet, such as Sinae Kim&rsquo;s <em>Genesis </em>(2001), have become inaccessible because viewing them requires the use of <span aria-hidden=\"true\">______</span><span class=\"sr-only\">blank</span> software (most notably Adobe Flash, discontinued in 2021).</p>","stem":"<p>Which choice completes the text with the most logical and precise word or phrase?</p>","answerOptions":[{"id":"00c9c035-bf32-4db7-b1d5-0e66f409c904","content":"<p>defunct</p>"},{"id":"a0f4b726-7c3a-4b19-8894-97688a491885","content":"<p>arcane</p>"},{"id":"b5ec70de-950e-4497-823f-87504d5d6159","content":"<p>ubiquitous</p>"},{"id":"1e34cd76-6b1f-46f7-b624-a91bd40183dc","content":"<p>extraneous</p>"}],"keys":["00c9c035-bf32-4db7-b1d5-0e66f409c904"],"correct_answer":["A"],"rationale":"<p>Choice A is the best answer because it most logically completes the text&rsquo;s discussion of artworks that were produced for exhibition on the internet. In this context, \"defunct\" means no longer existing or functioning. According to the text, many artworks that were produced in the mid-1990s to the early 2000s for exhibition on the internet have become inaccessible due to their reliance on certain software. As an example, the text cites Sinae Kim&rsquo;s <em>Genesis</em>, which relied on software that was discontinued in 2021. This context supports the idea that the software is defunct.</p><p>Choice B is incorrect because the text indicates that viewing artworks produced in the mid-1990s to the early 2000s for exhibition on the internet requires the use of software. Artists generally want their works to be seen by many people, so it wouldn&rsquo;t make sense for creators of internet art to require the use of software that is \"arcane,\" or known or knowable to only a few people. Moreover, the text states that a prominent example of software used to view these artworks is Adobe Flash, which was discontinued in 2021, meaning it&rsquo;s now defunct. Choice C is incorrect because \"ubiquitous\" would mean found everywhere, which wouldn&rsquo;t make sense in this context. The text indicates that the reason why many artworks that were produced in the mid-1990s to the early 2000s for exhibition on the internet have become inaccessible has to do with the software required for viewing them. According to the text, one example of such software is Adobe Flash, which was discontinued in 2021, meaning it&rsquo;s now defunct. Choice D is incorrect because nothing in the text suggests that the software used to view artworks produced in the mid-1990s to the early 2000s for exhibition on the internet is \"extraneous,\" or irrelevant. Instead, the text indicates that use of specific software is required to view certain artworks from this period and that the discontinuation of the software renders the works inaccessible.</p>","parenttemplatename":null,"parenttemplateid":null,"templateclusterid":null,"templateclustername":null,"origin":null,"position":null,"createDate":1730147323042,"updateDate":1730147323042}$SATQ$::jsonb, 1730147323042, 1730147323042),
    ($SATQ$a20b7511$SATQ$, $SATQ$a0c24ca5-51c5-452d-8ec0-5c2da945b392$SATQ$::uuid, NULL, NULL, $SATQ$qbank$SATQ$, $SATQ$SAT$SATQ$, 1, $SATQ$Reading and Writing$SATQ$, $SATQ$Craft and Structure$SATQ$, $SATQ$CAS$SATQ$, $SATQ$WIC$SATQ$, $SATQ$Words in Context$SATQ$, $SATQ$E$SATQ$, 3, $SATQ$mcq$SATQ$, $SATQ$<p>Scholars long thought that the initial spread of silk beyond China occurred in the second century CE, but this view has been <span aria-hidden="true">______</span><span class="sr-only">blank</span> by new archaeological evidence from South Asia that reveals that the people of the Indus Civilization made use of silk at least 1,000 years earlier.</p>$SATQ$, $SATQ$<p>Which choice completes the text with the most logical and precise word or phrase?</p>$SATQ$, $SATQ$[{"id":"fa5a0f8c-744e-45e1-9f6b-01c81574c750","content":"<p>investigated</p>"},{"id":"2f10eddb-2fcc-47dd-82ed-e5fd27ae9d9f","content":"<p>misinterpreted</p>"},{"id":"7026061a-7ae3-461f-8833-80c9b4e747a6","content":"<p>anticipated</p>"},{"id":"ecbcd5f4-8266-4af5-bd5e-a0f2ad6bc3f8","content":"<p>contradicted</p>"}]$SATQ$::jsonb, $SATQ$["D"]$SATQ$::jsonb, $SATQ$["ecbcd5f4-8266-4af5-bd5e-a0f2ad6bc3f8"]$SATQ$::jsonb, $SATQ$<p>Choice D is the best answer because it most logically completes the text&rsquo;s discussion of the initial spread of silk beyond China. In this context, &ldquo;contradicted&rdquo; means opposed or challenged. The text indicates that new archaeological evidence about silk use in South Asia has done something to a long-held thought about the initial spread of silk. According to the text, the new evidence reveals that people used silk in South Asia 1,000 years before the second century CE, which directly challenges the previous belief that silk first spread beyond China in the second century CE.</p><p>Choice A is incorrect because the text indicates that an archaeological finding about silk use has done something to a long-held thought about the initial spread of silk, and it wouldn&rsquo;t make sense to suggest that the finding could have &ldquo;investigated,&rdquo; or examined, a belief; evidence can&rsquo;t examine anything. Choice B is incorrect because the text indicates that an archaeological finding about silk use has done something to a long-held thought about the initial spread of silk, and it wouldn&rsquo;t make sense to suggest that the finding could have &ldquo;misinterpreted,&rdquo; or incorrectly understood, a belief; evidence can&rsquo;t try to understand anything. Choice C is incorrect. In this context, &ldquo;anticipated&rdquo; would mean expected or predicted. The text indicates that a new archaeological finding about silk use has done something to a long-held thought about the initial spread of silk, and a new finding can&rsquo;t predict a belief that is already established.</p>$SATQ$, false, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, $SATQ${"questionId":"a20b7511","external_id":"a0c24ca5-51c5-452d-8ec0-5c2da945b392","vaultid":null,"uId":"8e8a440f-d838-4bb2-b1af-d343f44c0fd4","program":"SAT","test_type":1,"test_type_desc":"Reading and Writing","primary_class_cd":"CAS","domain":"Craft and Structure","skill_cd":"WIC","skill_desc":"Words in Context","difficulty":"E","score_band_range_cd":3,"type":"mcq","stimulus":"<p>Scholars long thought that the initial spread of silk beyond China occurred in the second century CE, but this view has been <span aria-hidden=\"true\">______</span><span class=\"sr-only\">blank</span> by new archaeological evidence from South Asia that reveals that the people of the Indus Civilization made use of silk at least 1,000 years earlier.</p>","stem":"<p>Which choice completes the text with the most logical and precise word or phrase?</p>","answerOptions":[{"id":"fa5a0f8c-744e-45e1-9f6b-01c81574c750","content":"<p>investigated</p>"},{"id":"2f10eddb-2fcc-47dd-82ed-e5fd27ae9d9f","content":"<p>misinterpreted</p>"},{"id":"7026061a-7ae3-461f-8833-80c9b4e747a6","content":"<p>anticipated</p>"},{"id":"ecbcd5f4-8266-4af5-bd5e-a0f2ad6bc3f8","content":"<p>contradicted</p>"}],"keys":["ecbcd5f4-8266-4af5-bd5e-a0f2ad6bc3f8"],"correct_answer":["D"],"rationale":"<p>Choice D is the best answer because it most logically completes the text&rsquo;s discussion of the initial spread of silk beyond China. In this context, &ldquo;contradicted&rdquo; means opposed or challenged. The text indicates that new archaeological evidence about silk use in South Asia has done something to a long-held thought about the initial spread of silk. According to the text, the new evidence reveals that people used silk in South Asia 1,000 years before the second century CE, which directly challenges the previous belief that silk first spread beyond China in the second century CE.</p><p>Choice A is incorrect because the text indicates that an archaeological finding about silk use has done something to a long-held thought about the initial spread of silk, and it wouldn&rsquo;t make sense to suggest that the finding could have &ldquo;investigated,&rdquo; or examined, a belief; evidence can&rsquo;t examine anything. Choice B is incorrect because the text indicates that an archaeological finding about silk use has done something to a long-held thought about the initial spread of silk, and it wouldn&rsquo;t make sense to suggest that the finding could have &ldquo;misinterpreted,&rdquo; or incorrectly understood, a belief; evidence can&rsquo;t try to understand anything. Choice C is incorrect. In this context, &ldquo;anticipated&rdquo; would mean expected or predicted. The text indicates that a new archaeological finding about silk use has done something to a long-held thought about the initial spread of silk, and a new finding can&rsquo;t predict a belief that is already established.</p>","parenttemplatename":null,"parenttemplateid":null,"templateclusterid":null,"templateclustername":null,"origin":null,"position":null,"createDate":1776362771169,"updateDate":1776362771169}$SATQ$::jsonb, 1776362771169, 1776362771169),
    ($SATQ$a2835734$SATQ$, $SATQ$0dedefd3-51a0-4b69-8d27-70bd2b8d1fc2$SATQ$::uuid, $SATQ$5f6e6e1a-408e-4b60-a4b6-5dca0fab7f5a$SATQ$::uuid, NULL, $SATQ$qbank$SATQ$, $SATQ$SAT$SATQ$, 1, $SATQ$Reading and Writing$SATQ$, $SATQ$Craft and Structure$SATQ$, $SATQ$CAS$SATQ$, $SATQ$WIC$SATQ$, $SATQ$Words in Context$SATQ$, $SATQ$E$SATQ$, 2, $SATQ$mcq$SATQ$, $SATQ$<p>Visual artist Gabriela Alem&aacute;n states that the bold colors of comics, pop art, and Latinx culture have always fascinated her. This passion for the rich history and colors of her Latinx community translates into the <span aria-hidden="true">______</span><span class="sr-only">blank</span> artworks she produces.</p>$SATQ$, $SATQ$<p>Which choice completes the text with the most logical and precise word or phrase?</p>$SATQ$, $SATQ$[{"id":"103806c6-50f5-4ef2-8b93-d8932e6a52d0","content":"<p>vivid</p>"},{"id":"58ec06c1-115e-42e5-9f51-3644d7cbfee3","content":"<p>unknown</p>"},{"id":"1350d17c-0f39-4498-9fd4-3bb849e01271","content":"<p>definite</p>"},{"id":"cc072aa0-1627-4b8d-944d-f2f83a4879a3","content":"<p>reserved</p>"}]$SATQ$::jsonb, $SATQ$["A"]$SATQ$::jsonb, $SATQ$["103806c6-50f5-4ef2-8b93-d8932e6a52d0"]$SATQ$::jsonb, $SATQ$<p>Choice A is the best answer. "Vivid" can mean "colorful" or "bright-colored." This definition fits the context clues about Alem&aacute;n&rsquo;s fascination with and passion for bold colors.</p><p>Choice B is incorrect. This doesn&rsquo;t fit the logic of the text. Nothing in the text indicates that Alem&aacute;n&rsquo;s artworks are "unknown." Choice C is incorrect. This doesn&rsquo;t fit the logic of the text. "Definite" means "certain" or "decided." It wouldn&rsquo;t make sense to describe artwork as "definite." Choice D is incorrect. This doesn&rsquo;t fit the logic of the text. "Reserved" can either mean "slow to reveal emotions" or "booked." But the clues suggest that Alem&aacute;n&rsquo;s artworks are boldly colorful&mdash;almost the opposite of "reserved."</p>$SATQ$, false, 0, $SATQ$OSP-KA-WIC-E002$SATQ$, $SATQ$$SATQ$, $SATQ$e24cf8d9-a82d-4621-aa37-e295e4715c4a$SATQ$::uuid, $SATQ$$SATQ$, $SATQ$proteus$SATQ$, $SATQ$0$SATQ$, NULL, NULL, $SATQ${"questionId":"a2835734","external_id":"0dedefd3-51a0-4b69-8d27-70bd2b8d1fc2","vaultid":"5f6e6e1a-408e-4b60-a4b6-5dca0fab7f5a","uId":"3545f76d-f587-4871-a958-c1fe7d2d2e90","program":"SAT","test_type":1,"test_type_desc":"Reading and Writing","primary_class_cd":"CAS","domain":"Craft and Structure","skill_cd":"WIC","skill_desc":"Words in Context","difficulty":"E","score_band_range_cd":2,"type":"mcq","stimulus":"<p>Visual artist Gabriela Alem&aacute;n states that the bold colors of comics, pop art, and Latinx culture have always fascinated her. This passion for the rich history and colors of her Latinx community translates into the <span aria-hidden=\"true\">______</span><span class=\"sr-only\">blank</span> artworks she produces.</p>","stem":"<p>Which choice completes the text with the most logical and precise word or phrase?</p>","answerOptions":[{"id":"103806c6-50f5-4ef2-8b93-d8932e6a52d0","content":"<p>vivid</p>"},{"id":"58ec06c1-115e-42e5-9f51-3644d7cbfee3","content":"<p>unknown</p>"},{"id":"1350d17c-0f39-4498-9fd4-3bb849e01271","content":"<p>definite</p>"},{"id":"cc072aa0-1627-4b8d-944d-f2f83a4879a3","content":"<p>reserved</p>"}],"keys":["103806c6-50f5-4ef2-8b93-d8932e6a52d0"],"correct_answer":["A"],"rationale":"<p>Choice A is the best answer. \"Vivid\" can mean \"colorful\" or \"bright-colored.\" This definition fits the context clues about Alem&aacute;n&rsquo;s fascination with and passion for bold colors.</p><p>Choice B is incorrect. This doesn&rsquo;t fit the logic of the text. Nothing in the text indicates that Alem&aacute;n&rsquo;s artworks are \"unknown.\" Choice C is incorrect. This doesn&rsquo;t fit the logic of the text. \"Definite\" means \"certain\" or \"decided.\" It wouldn&rsquo;t make sense to describe artwork as \"definite.\" Choice D is incorrect. This doesn&rsquo;t fit the logic of the text. \"Reserved\" can either mean \"slow to reveal emotions\" or \"booked.\" But the clues suggest that Alem&aacute;n&rsquo;s artworks are boldly colorful&mdash;almost the opposite of \"reserved.\"</p>","parenttemplatename":"OSP-KA-WIC-E002","parenttemplateid":"","templateclusterid":"e24cf8d9-a82d-4621-aa37-e295e4715c4a","templateclustername":"","origin":"proteus","position":"0","createDate":1691007959377,"updateDate":1691007959377}$SATQ$::jsonb, 1691007959377, 1691007959377),
    ($SATQ$a2be625e$SATQ$, $SATQ$8a008194-d038-44b2-968e-fcbc15789b3c$SATQ$::uuid, NULL, NULL, $SATQ$qbank$SATQ$, $SATQ$SAT$SATQ$, 1, $SATQ$Reading and Writing$SATQ$, $SATQ$Craft and Structure$SATQ$, $SATQ$CAS$SATQ$, $SATQ$TSP$SATQ$, $SATQ$Text Structure and Purpose$SATQ$, $SATQ$M$SATQ$, 4, $SATQ$mcq$SATQ$, $SATQ$<p>The following text is from Sarah Orne Jewett&rsquo;s <span data-ssml-say-as="date">1899</span> short story &ldquo;Martha&rsquo;s Lady.&rdquo; Martha is employed by Miss Pyne as a maid.&nbsp;</p>
<blockquote>
<p>Miss Pyne sat by the window watching, in her best dress, looking stately and calm; she seldom went out now, and it was almost time for the carriage. Martha was just coming in from the garden with the strawberries, and with more flowers in her apron. It was a bright cool evening in June, the golden robins sang in the elms, and the sun was going down behind the apple-trees at the foot of the garden. The beautiful old house stood wide open to the long-expected guest.</p>
</blockquote>$SATQ$, $SATQ$<p>Which choice best states the main purpose of the text?</p>$SATQ$, $SATQ$[{"id":"08b60343-2624-4db5-b4da-940b4abd9455","content":"<p>To convey the worries brought about by a new guest</p>"},{"id":"0ae29377-5626-4dfa-a652-621e574bfffc","content":"<p>To describe how the characters have changed over time</p>"},{"id":"1ab0675e-3a54-4640-8721-93f17651d323","content":"<p>To contrast the activity indoors with the stillness outside</p>"},{"id":"f29827a7-f248-43a3-8451-4f7fe65268ee","content":"<p>To depict the setting as the characters await a visitor&rsquo;s arrival&nbsp;</p>"}]$SATQ$::jsonb, $SATQ$["D"]$SATQ$::jsonb, $SATQ$["f29827a7-f248-43a3-8451-4f7fe65268ee"]$SATQ$::jsonb, $SATQ$<p>Choice D is the best answer because it most accurately reflects the main purpose of the text. The text portrays Miss Pyne as awaiting the arrival of a carriage while Martha brings strawberries and flowers from the garden into the house. The text also describes the surroundings of the scene, stating that Miss Pyne looks "stately and calm," the evening is bright and cool, and birds are singing in the garden as the sun sets. Then the last sentence states that the house was "wide open to the long-expected guest," which strongly suggests that Miss Pyne&rsquo;s anticipation and Martha&rsquo;s activities were in preparation for the guest who is expected to arrive in the carriage. Thus, the text depicts the setting and conveys what these characters are doing as they await the arrival of their visitor.</p><p>Choice A is incorrect because there is nothing in the text to indicate that the characters feel any worry about the guest&rsquo;s arrival. The text indicates that the guest was "long-expected," but characterizing Miss Pyne as "stately and calm" conflicts with the idea that the characters are worried about the guest. Choice B is incorrect because the text describes a moment in time when two characters are awaiting the arrival of a visitor rather than an extended period over which characters could be seen changing. Choice C is incorrect. Although the text describes the activity indoors (Miss Pyne sitting calmly), it describes a higher level of activity, not stillness, outside (Martha bringing fruit and flowers and birds singing).</p>$SATQ$, false, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, $SATQ${"questionId":"a2be625e","external_id":"8a008194-d038-44b2-968e-fcbc15789b3c","vaultid":null,"uId":"c1003325-7bbc-4d51-93e2-c27bf1a3917d","program":"SAT","test_type":1,"test_type_desc":"Reading and Writing","primary_class_cd":"CAS","domain":"Craft and Structure","skill_cd":"TSP","skill_desc":"Text Structure and Purpose","difficulty":"M","score_band_range_cd":4,"type":"mcq","stimulus":"<p>The following text is from Sarah Orne Jewett&rsquo;s <span data-ssml-say-as=\"date\">1899</span> short story &ldquo;Martha&rsquo;s Lady.&rdquo; Martha is employed by Miss Pyne as a maid.&nbsp;</p>\n<blockquote>\n<p>Miss Pyne sat by the window watching, in her best dress, looking stately and calm; she seldom went out now, and it was almost time for the carriage. Martha was just coming in from the garden with the strawberries, and with more flowers in her apron. It was a bright cool evening in June, the golden robins sang in the elms, and the sun was going down behind the apple-trees at the foot of the garden. The beautiful old house stood wide open to the long-expected guest.</p>\n</blockquote>","stem":"<p>Which choice best states the main purpose of the text?</p>","answerOptions":[{"id":"08b60343-2624-4db5-b4da-940b4abd9455","content":"<p>To convey the worries brought about by a new guest</p>"},{"id":"0ae29377-5626-4dfa-a652-621e574bfffc","content":"<p>To describe how the characters have changed over time</p>"},{"id":"1ab0675e-3a54-4640-8721-93f17651d323","content":"<p>To contrast the activity indoors with the stillness outside</p>"},{"id":"f29827a7-f248-43a3-8451-4f7fe65268ee","content":"<p>To depict the setting as the characters await a visitor&rsquo;s arrival&nbsp;</p>"}],"keys":["f29827a7-f248-43a3-8451-4f7fe65268ee"],"correct_answer":["D"],"rationale":"<p>Choice D is the best answer because it most accurately reflects the main purpose of the text. The text portrays Miss Pyne as awaiting the arrival of a carriage while Martha brings strawberries and flowers from the garden into the house. The text also describes the surroundings of the scene, stating that Miss Pyne looks \"stately and calm,\" the evening is bright and cool, and birds are singing in the garden as the sun sets. Then the last sentence states that the house was \"wide open to the long-expected guest,\" which strongly suggests that Miss Pyne&rsquo;s anticipation and Martha&rsquo;s activities were in preparation for the guest who is expected to arrive in the carriage. Thus, the text depicts the setting and conveys what these characters are doing as they await the arrival of their visitor.</p><p>Choice A is incorrect because there is nothing in the text to indicate that the characters feel any worry about the guest&rsquo;s arrival. The text indicates that the guest was \"long-expected,\" but characterizing Miss Pyne as \"stately and calm\" conflicts with the idea that the characters are worried about the guest. Choice B is incorrect because the text describes a moment in time when two characters are awaiting the arrival of a visitor rather than an extended period over which characters could be seen changing. Choice C is incorrect. Although the text describes the activity indoors (Miss Pyne sitting calmly), it describes a higher level of activity, not stillness, outside (Martha bringing fruit and flowers and birds singing).</p>","parenttemplatename":null,"parenttemplateid":null,"templateclusterid":null,"templateclustername":null,"origin":null,"position":null,"createDate":1691007959320,"updateDate":1691007959320}$SATQ$::jsonb, 1691007959320, 1691007959320),
    ($SATQ$a2dd51c1$SATQ$, $SATQ$ed628125-1859-4622-bafa-5fd5cd10bbdd$SATQ$::uuid, $SATQ$a4c947e7-2034-4867-9ea8-8370ad56ab03$SATQ$::uuid, NULL, $SATQ$qbank$SATQ$, $SATQ$SAT$SATQ$, 1, $SATQ$Reading and Writing$SATQ$, $SATQ$Craft and Structure$SATQ$, $SATQ$CAS$SATQ$, $SATQ$TSP$SATQ$, $SATQ$Text Structure and Purpose$SATQ$, $SATQ$E$SATQ$, 2, $SATQ$mcq$SATQ$, $SATQ$<p>In most building demolitions, the building materials are destroyed and sent to landfills. City officials in Portland, Oregon, wanted to reduce this waste. The officials passed a law requiring demolition companies to deconstruct some buildings instead. Deconstruction involves carefully taking buildings apart piece by piece. Damage to the materials is avoided so that they can be reused in new constructions. A 2019 study found that 27 percent of materials from deconstructions in Portland were able to be reused. The remaining materials were processed for recycling instead of going to a landfill.</p>$SATQ$, $SATQ$<p>Which choice best states the main purpose of the text?</p>$SATQ$, $SATQ$[{"id":"a8551659-f93c-4821-ad0f-5923e69862cd","content":"<p>To explain an effort made by the city of Portland to reduce demolition waste and some results of that effort&nbsp;</p>"},{"id":"c0fb133a-b922-4bc7-997f-faa455b1fa9d","content":"<p>To show that popular support for measures that reduce demolition waste has increased since 2019</p>"},{"id":"771977d7-ab7e-4842-b737-f8755316f93c","content":"<p>To argue that building deconstruction is not as effective as other measures at reducing demolition waste</p>"},{"id":"68aa2fc5-91d1-4cba-82bd-e5883ce49732","content":"<p>To discuss laws aimed to reduce demolition waste in Portland and compare them to similar laws in other cities&nbsp;</p>"}]$SATQ$::jsonb, $SATQ$["A"]$SATQ$::jsonb, $SATQ$["a8551659-f93c-4821-ad0f-5923e69862cd"]$SATQ$::jsonb, $SATQ$<p>Choice A is the best answer. The author first describes a Portland law aimed at reducing demolition waste, and then goes on to explain that 27% of materials from building deconstructions were able to be reused and the rest were recycled. </p><p>Choice B is incorrect. The text never discusses the popularity of the law. Choice C is incorrect. The text never compares building deconstruction to other measures designed to reduce demolition waste. Choice D is incorrect. The text never mentions laws in cities other than Portland, Oregon. </p>$SATQ$, false, 0, $SATQ$OSP-KA-TSP-E008$SATQ$, $SATQ$$SATQ$, $SATQ$69e4b2ed-0591-432e-843f-ceae81fd0eca$SATQ$::uuid, $SATQ$$SATQ$, $SATQ$proteus$SATQ$, $SATQ$0$SATQ$, NULL, NULL, $SATQ${"questionId":"a2dd51c1","external_id":"ed628125-1859-4622-bafa-5fd5cd10bbdd","vaultid":"a4c947e7-2034-4867-9ea8-8370ad56ab03","uId":"81e3f6f7-1778-4ead-90bb-961faaffe78b","program":"SAT","test_type":1,"test_type_desc":"Reading and Writing","primary_class_cd":"CAS","domain":"Craft and Structure","skill_cd":"TSP","skill_desc":"Text Structure and Purpose","difficulty":"E","score_band_range_cd":2,"type":"mcq","stimulus":"<p>In most building demolitions, the building materials are destroyed and sent to landfills. City officials in Portland, Oregon, wanted to reduce this waste. The officials passed a law requiring demolition companies to deconstruct some buildings instead. Deconstruction involves carefully taking buildings apart piece by piece. Damage to the materials is avoided so that they can be reused in new constructions. A 2019 study found that 27 percent of materials from deconstructions in Portland were able to be reused. The remaining materials were processed for recycling instead of going to a landfill.</p>","stem":"<p>Which choice best states the main purpose of the text?</p>","answerOptions":[{"id":"a8551659-f93c-4821-ad0f-5923e69862cd","content":"<p>To explain an effort made by the city of Portland to reduce demolition waste and some results of that effort&nbsp;</p>"},{"id":"c0fb133a-b922-4bc7-997f-faa455b1fa9d","content":"<p>To show that popular support for measures that reduce demolition waste has increased since 2019</p>"},{"id":"771977d7-ab7e-4842-b737-f8755316f93c","content":"<p>To argue that building deconstruction is not as effective as other measures at reducing demolition waste</p>"},{"id":"68aa2fc5-91d1-4cba-82bd-e5883ce49732","content":"<p>To discuss laws aimed to reduce demolition waste in Portland and compare them to similar laws in other cities&nbsp;</p>"}],"keys":["a8551659-f93c-4821-ad0f-5923e69862cd"],"correct_answer":["A"],"rationale":"<p>Choice A is the best answer. The author first describes a Portland law aimed at reducing demolition waste, and then goes on to explain that 27% of materials from building deconstructions were able to be reused and the rest were recycled. </p><p>Choice B is incorrect. The text never discusses the popularity of the law. Choice C is incorrect. The text never compares building deconstruction to other measures designed to reduce demolition waste. Choice D is incorrect. The text never mentions laws in cities other than Portland, Oregon. </p>","parenttemplatename":"OSP-KA-TSP-E008","parenttemplateid":"","templateclusterid":"69e4b2ed-0591-432e-843f-ceae81fd0eca","templateclustername":"","origin":"proteus","position":"0","createDate":1691007959374,"updateDate":1691007959374}$SATQ$::jsonb, 1691007959374, 1691007959374),
    ($SATQ$a2f64e58$SATQ$, $SATQ$1620c171-f321-4ee4-a855-19c83d327964$SATQ$::uuid, NULL, NULL, $SATQ$qbank$SATQ$, $SATQ$SAT$SATQ$, 1, $SATQ$Reading and Writing$SATQ$, $SATQ$Craft and Structure$SATQ$, $SATQ$CAS$SATQ$, $SATQ$TSP$SATQ$, $SATQ$Text Structure and Purpose$SATQ$, $SATQ$H$SATQ$, 7, $SATQ$mcq$SATQ$, $SATQ$<p><span style="text-decoration: underline;" role="region" aria-label="Referenced Content">Individual elephants and Arctic herbivores such as caribou tend to have fixed geographic ranges throughout their lifetimes,</span> which had prompted some researchers to speculate that the Arctic woolly mammoth, an extinct elephantid, might have exhibited similar behavior. Mammoth tusks grew in sequential layers, incorporating ingested minerals and organics, and so each ivory stratum reflects the ratio of strontium isotopes (<sup>87</sup><span data-ssml-say-as="characters">Sr</span>/<sup>86</sup><span data-ssml-say-as="characters">Sr</span>) in the local environment; thus, the sequence of strata shows where the animal roamed during life. Recent analysis of the strontium ratios in the strata of one Arctic woolly mammoth tusk in relation to the geographic distribution of strontium ratios in the environment shows the animal&rsquo;s range begin to expand as it reached sexual maturity, only to contract again in its final 1.5 years.</p>$SATQ$, $SATQ$<p>Which choice best describes the function of the underlined statement in the text as a whole?</p>$SATQ$, $SATQ$[{"id":"35ca57b6-898d-4b5a-b5e5-fbff49412d0f","content":"<p>It discusses a characteristic shared by certain animals in order to explain why researchers raised a possibility that turned out not to be supported by data described later in the text.</p>"},{"id":"a7e2d659-5432-4ced-a17e-2dd80144cc75","content":"<p>It illustrates a pattern of behavior among certain animals in order to present a theory about exceptions to that pattern that is weakened by a finding described later in the text.</p>"},{"id":"12b24a0c-b9a6-43d7-9a66-8e940881873b","content":"<p>It describes a similarity in the behavior of certain animals in order to show why a method described later in the text did not reveal whether another animal also showed that behavior.</p>"},{"id":"f6d4bff3-d1a6-4928-abb8-e26b1c2aaa73","content":"<p>It introduces a trait shared by certain animals in order to contextualize a hypothesis about the origin of that trait that is advanced later in the text.</p>"}]$SATQ$::jsonb, $SATQ$["A"]$SATQ$::jsonb, $SATQ$["35ca57b6-898d-4b5a-b5e5-fbff49412d0f"]$SATQ$::jsonb, $SATQ$<p>Choice A is the best answer because it most accurately describes how the underlined statement functions in the text as a whole. The underlined statement mentions a category of animals that have a feature in common: they tend to have fixed geographic ranges throughout their lifetimes. The text then presents the speculation of some researchers that the Arctic woolly mammoth might also share this characteristic. However, an examination of the content of strontium in the strata (or layers) of a woolly mammoth tusk indicated that contrary to the researchers&rsquo; hypothesis, the mammoth had an expanding range in its environment that contracted in its last 1.5 years of life. Thus, the underlined statement discusses a characteristic shared by certain animals in order to explain why researchers raised a possibility that turned out not to be supported by data described later in the text.</p><p>Choice B is incorrect. Though the underlined statement presents a pattern of behavior (the habit of certain animals of staying within a fixed geographic range), the rest of the text does not present a theory of exceptions to that pattern; rather, the researchers are merely concerned with whether one particular animal has behavior consistent with the pattern. Choice C is incorrect. Though the underlined statement does describe a similarity in the behavior of certain animals (their tendency to stay within a fixed geographic range), this is not done in order to show why a method described later in the text failed to show whether another animal showed that behavior; rather, the method of analysis of strata of a woolly mammoth tusk showed that the mammoth&rsquo;s behavior was different from that of the animals mentioned in the underlined statement. Choice D is incorrect. Though the underlined statement mentions a trait shared by a number of animals (their fixed geographic range), the rest of the text does not present a hypothesis regarding the origin of that trait; rather, the researchers are concerned with whether another particular animal shares that trait.</p>$SATQ$, false, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, $SATQ${"questionId":"a2f64e58","external_id":"1620c171-f321-4ee4-a855-19c83d327964","vaultid":null,"uId":"38bf02b6-4e04-45bf-9f5f-3a8b5fafeb02","program":"SAT","test_type":1,"test_type_desc":"Reading and Writing","primary_class_cd":"CAS","domain":"Craft and Structure","skill_cd":"TSP","skill_desc":"Text Structure and Purpose","difficulty":"H","score_band_range_cd":7,"type":"mcq","stimulus":"<p><span style=\"text-decoration: underline;\" role=\"region\" aria-label=\"Referenced Content\">Individual elephants and Arctic herbivores such as caribou tend to have fixed geographic ranges throughout their lifetimes,</span> which had prompted some researchers to speculate that the Arctic woolly mammoth, an extinct elephantid, might have exhibited similar behavior. Mammoth tusks grew in sequential layers, incorporating ingested minerals and organics, and so each ivory stratum reflects the ratio of strontium isotopes (<sup>87</sup><span data-ssml-say-as=\"characters\">Sr</span>/<sup>86</sup><span data-ssml-say-as=\"characters\">Sr</span>) in the local environment; thus, the sequence of strata shows where the animal roamed during life. Recent analysis of the strontium ratios in the strata of one Arctic woolly mammoth tusk in relation to the geographic distribution of strontium ratios in the environment shows the animal&rsquo;s range begin to expand as it reached sexual maturity, only to contract again in its final 1.5 years.</p>","stem":"<p>Which choice best describes the function of the underlined statement in the text as a whole?</p>","answerOptions":[{"id":"35ca57b6-898d-4b5a-b5e5-fbff49412d0f","content":"<p>It discusses a characteristic shared by certain animals in order to explain why researchers raised a possibility that turned out not to be supported by data described later in the text.</p>"},{"id":"a7e2d659-5432-4ced-a17e-2dd80144cc75","content":"<p>It illustrates a pattern of behavior among certain animals in order to present a theory about exceptions to that pattern that is weakened by a finding described later in the text.</p>"},{"id":"12b24a0c-b9a6-43d7-9a66-8e940881873b","content":"<p>It describes a similarity in the behavior of certain animals in order to show why a method described later in the text did not reveal whether another animal also showed that behavior.</p>"},{"id":"f6d4bff3-d1a6-4928-abb8-e26b1c2aaa73","content":"<p>It introduces a trait shared by certain animals in order to contextualize a hypothesis about the origin of that trait that is advanced later in the text.</p>"}],"keys":["35ca57b6-898d-4b5a-b5e5-fbff49412d0f"],"correct_answer":["A"],"rationale":"<p>Choice A is the best answer because it most accurately describes how the underlined statement functions in the text as a whole. The underlined statement mentions a category of animals that have a feature in common: they tend to have fixed geographic ranges throughout their lifetimes. The text then presents the speculation of some researchers that the Arctic woolly mammoth might also share this characteristic. However, an examination of the content of strontium in the strata (or layers) of a woolly mammoth tusk indicated that contrary to the researchers&rsquo; hypothesis, the mammoth had an expanding range in its environment that contracted in its last 1.5 years of life. Thus, the underlined statement discusses a characteristic shared by certain animals in order to explain why researchers raised a possibility that turned out not to be supported by data described later in the text.</p><p>Choice B is incorrect. Though the underlined statement presents a pattern of behavior (the habit of certain animals of staying within a fixed geographic range), the rest of the text does not present a theory of exceptions to that pattern; rather, the researchers are merely concerned with whether one particular animal has behavior consistent with the pattern. Choice C is incorrect. Though the underlined statement does describe a similarity in the behavior of certain animals (their tendency to stay within a fixed geographic range), this is not done in order to show why a method described later in the text failed to show whether another animal showed that behavior; rather, the method of analysis of strata of a woolly mammoth tusk showed that the mammoth&rsquo;s behavior was different from that of the animals mentioned in the underlined statement. Choice D is incorrect. Though the underlined statement mentions a trait shared by a number of animals (their fixed geographic range), the rest of the text does not present a hypothesis regarding the origin of that trait; rather, the researchers are concerned with whether another particular animal shares that trait.</p>","parenttemplatename":null,"parenttemplateid":null,"templateclusterid":null,"templateclustername":null,"origin":null,"position":null,"createDate":1743430669203,"updateDate":1743430669203}$SATQ$::jsonb, 1743430669203, 1743430669203),
    ($SATQ$a318c1ef$SATQ$, $SATQ$11127b50-fc2e-4855-bc80-1d7d3c85764a$SATQ$::uuid, $SATQ$ad7ec619-d385-48ed-b7ff-94d9ad544eb1$SATQ$::uuid, NULL, $SATQ$qbank$SATQ$, $SATQ$SAT$SATQ$, 1, $SATQ$Reading and Writing$SATQ$, $SATQ$Craft and Structure$SATQ$, $SATQ$CAS$SATQ$, $SATQ$WIC$SATQ$, $SATQ$Words in Context$SATQ$, $SATQ$E$SATQ$, 3, $SATQ$mcq$SATQ$, $SATQ$<p>The Cambrian explosion gets its name from the sudden appearance and rapid diversification of animal remains in the fossil record about 541 million years ago, during the Cambrian period. Some scientists argue that this <span aria-hidden="true">______</span><span class="sr-only">blank</span> change in the fossil record might be because of a shift in many organisms to body types that were more likely to be preserved.</p>$SATQ$, $SATQ$<p>Which choice completes the text with the most logical and precise word or phrase?</p>$SATQ$, $SATQ$[{"id":"b29e0cfa-58b5-4b55-9575-903208b49a63","content":"<p>catastrophic</p>"},{"id":"6c0b86c0-e163-4a53-b1d9-b67badc9a44e","content":"<p>elusive</p>"},{"id":"52c28b9b-6e71-4c28-a328-6ea2223921c5","content":"<p>abrupt</p>"},{"id":"5f6febeb-351e-4893-87b7-97d8c6b72a0f","content":"<p>imminent</p>"}]$SATQ$::jsonb, $SATQ$["C"]$SATQ$::jsonb, $SATQ$["52c28b9b-6e71-4c28-a328-6ea2223921c5"]$SATQ$::jsonb, $SATQ$<p>Choice C is the best answer because it most logically and precisely completes the text&rsquo;s discussion of the fossil record from the Cambrian period. In this context, &ldquo;abrupt&rdquo; means sudden. The text explains that the fossil record reflects the unexpected appearance and rapid diversification, or increase in variety, of animal remains during the Cambrian period. This context establishes that these remains&rsquo; entry into the fossil record was sudden. </p><p>Choice A is incorrect. Although the word &ldquo;explosion&rdquo; appears in the name of the event marked by the fossil record change, the text never suggests that the change was &ldquo;catastrophic,&rdquo; or disastrous. In context, &ldquo;explosion&rdquo; refers to the rapid diversification, or the swift increase in variety, of animal remains in the fossil record&mdash;a phenomenon that the text presents in a relatively neutral manner, without commenting on whether it was negative or positive. Choice B is incorrect because the text never suggests that the change toward greater diversification is &ldquo;elusive,&rdquo; or difficult to locate, in the fossil record. Rather, the text notes that the change occurred about 541 million years ago, suggesting that scientists have indeed been able to locate it. Choice D is incorrect because it wouldn&rsquo;t make sense in context to describe the change in the fossil record as &ldquo;imminent,&rdquo; or about to occur, since the text indicates that the change already occurred millions of years ago. </p>$SATQ$, false, 0, $SATQ$OSP-938-WIC$SATQ$, $SATQ$$SATQ$, $SATQ$9794b1fe-2f0b-4187-86e6-30a8e6baec87$SATQ$::uuid, $SATQ$$SATQ$, $SATQ$proteus$SATQ$, $SATQ$0$SATQ$, NULL, NULL, $SATQ${"questionId":"a318c1ef","external_id":"11127b50-fc2e-4855-bc80-1d7d3c85764a","vaultid":"ad7ec619-d385-48ed-b7ff-94d9ad544eb1","uId":"c9abc550-ddf5-4bc5-9624-197535482bf0","program":"SAT","test_type":1,"test_type_desc":"Reading and Writing","primary_class_cd":"CAS","domain":"Craft and Structure","skill_cd":"WIC","skill_desc":"Words in Context","difficulty":"E","score_band_range_cd":3,"type":"mcq","stimulus":"<p>The Cambrian explosion gets its name from the sudden appearance and rapid diversification of animal remains in the fossil record about 541 million years ago, during the Cambrian period. Some scientists argue that this <span aria-hidden=\"true\">______</span><span class=\"sr-only\">blank</span> change in the fossil record might be because of a shift in many organisms to body types that were more likely to be preserved.</p>","stem":"<p>Which choice completes the text with the most logical and precise word or phrase?</p>","answerOptions":[{"id":"b29e0cfa-58b5-4b55-9575-903208b49a63","content":"<p>catastrophic</p>"},{"id":"6c0b86c0-e163-4a53-b1d9-b67badc9a44e","content":"<p>elusive</p>"},{"id":"52c28b9b-6e71-4c28-a328-6ea2223921c5","content":"<p>abrupt</p>"},{"id":"5f6febeb-351e-4893-87b7-97d8c6b72a0f","content":"<p>imminent</p>"}],"keys":["52c28b9b-6e71-4c28-a328-6ea2223921c5"],"correct_answer":["C"],"rationale":"<p>Choice C is the best answer because it most logically and precisely completes the text&rsquo;s discussion of the fossil record from the Cambrian period. In this context, &ldquo;abrupt&rdquo; means sudden. The text explains that the fossil record reflects the unexpected appearance and rapid diversification, or increase in variety, of animal remains during the Cambrian period. This context establishes that these remains&rsquo; entry into the fossil record was sudden. </p><p>Choice A is incorrect. Although the word &ldquo;explosion&rdquo; appears in the name of the event marked by the fossil record change, the text never suggests that the change was &ldquo;catastrophic,&rdquo; or disastrous. In context, &ldquo;explosion&rdquo; refers to the rapid diversification, or the swift increase in variety, of animal remains in the fossil record&mdash;a phenomenon that the text presents in a relatively neutral manner, without commenting on whether it was negative or positive. Choice B is incorrect because the text never suggests that the change toward greater diversification is &ldquo;elusive,&rdquo; or difficult to locate, in the fossil record. Rather, the text notes that the change occurred about 541 million years ago, suggesting that scientists have indeed been able to locate it. Choice D is incorrect because it wouldn&rsquo;t make sense in context to describe the change in the fossil record as &ldquo;imminent,&rdquo; or about to occur, since the text indicates that the change already occurred millions of years ago. </p>","parenttemplatename":"OSP-938-WIC","parenttemplateid":"","templateclusterid":"9794b1fe-2f0b-4187-86e6-30a8e6baec87","templateclustername":"","origin":"proteus","position":"0","createDate":1691007959356,"updateDate":1691007959356}$SATQ$::jsonb, 1691007959356, 1691007959356),
    ($SATQ$a3761c7e$SATQ$, $SATQ$40bb3e5d-a1dd-49ed-a57a-c8772051e9d2$SATQ$::uuid, $SATQ$9735a314-a512-4eae-af50-936935669396$SATQ$::uuid, NULL, $SATQ$qbank$SATQ$, $SATQ$SAT$SATQ$, 1, $SATQ$Reading and Writing$SATQ$, $SATQ$Craft and Structure$SATQ$, $SATQ$CAS$SATQ$, $SATQ$WIC$SATQ$, $SATQ$Words in Context$SATQ$, $SATQ$E$SATQ$, 2, $SATQ$mcq$SATQ$, $SATQ$<p>Physicist Joseph Weber performed <span aria-hidden="true">______</span><span class="sr-only">blank</span> work in gravitational wave research in the 1960s and 1970s, conducting key experiments that scientists later used as the basis for their own investigations that led to the first verified detection of a gravitational wave in 2015.</p>$SATQ$, $SATQ$<p>Which choice completes the text with the most logical and precise word or phrase?</p>$SATQ$, $SATQ$[{"id":"5309ff79-e524-44de-bdca-b70b63eba260","content":"<p>foundational</p>"},{"id":"a4d72050-7a61-46b4-845d-b6fe793f0b47","content":"<p>supplementary</p>"},{"id":"0ac1e107-6108-4fff-bed8-b85d79cfbcfe","content":"<p>repetitive</p>"},{"id":"dc8f2ede-9cd4-4832-889c-adac8f1ef014","content":"<p>ineffective</p>"}]$SATQ$::jsonb, $SATQ$["A"]$SATQ$::jsonb, $SATQ$["5309ff79-e524-44de-bdca-b70b63eba260"]$SATQ$::jsonb, $SATQ$<p>Choice A is the best answer because it most logically completes the text&rsquo;s discussion of physicist Joseph Webster&rsquo;s research on gravitational waves. In this context &ldquo;foundational&rdquo; means the basis on which something else develops. The text indicates that Webster&rsquo;s experiments in the 1960s and 1970s were earlier than, and &ldquo;key&rdquo; to, the work of later scientists in the field; thus, Webster&rsquo;s work was foundational to the later scientists&rsquo; experiments and the eventual detection of a gravitational wave in 2015. &nbsp;</p><p>Choice B is incorrect because the text does not suggest that Webster&rsquo;s work was supplementary, or an additional element of an existing, larger project, but rather it was &ldquo;the basis for&rdquo; later experiments. Choice C is incorrect because the text does not assert that Webster&rsquo;s work was repetitive, or involved doing something the same way many times. Rather, the text indicates that Webster&rsquo;s work formed the basis for later investigations in the field of gravitational wave research. &nbsp;Choice D is incorrect because the text does not state that Webster&rsquo;s work was ineffective, or failed to produce the desired outcome. Rather, the text strongly implies that Webster&rsquo;s work was productive and extremely important to later work in the field of gravitational wave research.&nbsp;</p>$SATQ$, false, 0, $SATQ$OSP-016-WIC$SATQ$, $SATQ$$SATQ$, $SATQ$3588ac2e-ee07-46ff-b6eb-8fd6e95c98b2$SATQ$::uuid, $SATQ$$SATQ$, $SATQ$proteus$SATQ$, $SATQ$0$SATQ$, NULL, NULL, $SATQ${"questionId":"a3761c7e","external_id":"40bb3e5d-a1dd-49ed-a57a-c8772051e9d2","vaultid":"9735a314-a512-4eae-af50-936935669396","uId":"8e006a8c-674f-42de-b3e9-5101d31f7e49","program":"SAT","test_type":1,"test_type_desc":"Reading and Writing","primary_class_cd":"CAS","domain":"Craft and Structure","skill_cd":"WIC","skill_desc":"Words in Context","difficulty":"E","score_band_range_cd":2,"type":"mcq","stimulus":"<p>Physicist Joseph Weber performed <span aria-hidden=\"true\">______</span><span class=\"sr-only\">blank</span> work in gravitational wave research in the 1960s and 1970s, conducting key experiments that scientists later used as the basis for their own investigations that led to the first verified detection of a gravitational wave in 2015.</p>","stem":"<p>Which choice completes the text with the most logical and precise word or phrase?</p>","answerOptions":[{"id":"5309ff79-e524-44de-bdca-b70b63eba260","content":"<p>foundational</p>"},{"id":"a4d72050-7a61-46b4-845d-b6fe793f0b47","content":"<p>supplementary</p>"},{"id":"0ac1e107-6108-4fff-bed8-b85d79cfbcfe","content":"<p>repetitive</p>"},{"id":"dc8f2ede-9cd4-4832-889c-adac8f1ef014","content":"<p>ineffective</p>"}],"keys":["5309ff79-e524-44de-bdca-b70b63eba260"],"correct_answer":["A"],"rationale":"<p>Choice A is the best answer because it most logically completes the text&rsquo;s discussion of physicist Joseph Webster&rsquo;s research on gravitational waves. In this context &ldquo;foundational&rdquo; means the basis on which something else develops. The text indicates that Webster&rsquo;s experiments in the 1960s and 1970s were earlier than, and &ldquo;key&rdquo; to, the work of later scientists in the field; thus, Webster&rsquo;s work was foundational to the later scientists&rsquo; experiments and the eventual detection of a gravitational wave in 2015. &nbsp;</p><p>Choice B is incorrect because the text does not suggest that Webster&rsquo;s work was supplementary, or an additional element of an existing, larger project, but rather it was &ldquo;the basis for&rdquo; later experiments. Choice C is incorrect because the text does not assert that Webster&rsquo;s work was repetitive, or involved doing something the same way many times. Rather, the text indicates that Webster&rsquo;s work formed the basis for later investigations in the field of gravitational wave research. &nbsp;Choice D is incorrect because the text does not state that Webster&rsquo;s work was ineffective, or failed to produce the desired outcome. Rather, the text strongly implies that Webster&rsquo;s work was productive and extremely important to later work in the field of gravitational wave research.&nbsp;</p>","parenttemplatename":"OSP-016-WIC","parenttemplateid":"","templateclusterid":"3588ac2e-ee07-46ff-b6eb-8fd6e95c98b2","templateclustername":"","origin":"proteus","position":"0","createDate":1691007959316,"updateDate":1691007959316}$SATQ$::jsonb, 1691007959316, 1691007959316),
    ($SATQ$a49500cc$SATQ$, $SATQ$f92df5e5-64e5-4ca2-90a2-cabd8a1c6b00$SATQ$::uuid, NULL, NULL, $SATQ$qbank$SATQ$, $SATQ$SAT$SATQ$, 1, $SATQ$Reading and Writing$SATQ$, $SATQ$Craft and Structure$SATQ$, $SATQ$CAS$SATQ$, $SATQ$WIC$SATQ$, $SATQ$Words in Context$SATQ$, $SATQ$E$SATQ$, 1, $SATQ$mcq$SATQ$, $SATQ$<p>Predatory animals differ widely in how they <span aria-hidden="true">______</span><span class="sr-only">blank</span> food for their young. Some leave dead prey nearby for their young to consume, some bring live prey to their young, and some feed their young directly from their own mouths.&nbsp;</p>$SATQ$, $SATQ$<p>Which choice completes the text with the most logical and precise word or phrase?</p>$SATQ$, $SATQ$[{"id":"fac1e181-880d-4962-8e68-0b3c3de77eeb","content":"<p>avoid</p>"},{"id":"7b35e9a4-3d26-4ff5-be5c-36ce253a4728","content":"<p>guess</p>"},{"id":"b219fbc3-ca1f-4f08-a6bb-8a8b47915575","content":"<p>provide</p>"},{"id":"cb7fa8c8-b62d-4f7e-bb97-ce7f89164c46","content":"<p>describe</p>"}]$SATQ$::jsonb, $SATQ$["C"]$SATQ$::jsonb, $SATQ$["b219fbc3-ca1f-4f08-a6bb-8a8b47915575"]$SATQ$::jsonb, $SATQ$<p>Choice C is the best answer because it most logically completes the text&rsquo;s discussion of how predators feed their young. As used in this context, "provide" means supply or make something that&rsquo;s needed available. The text indicates that some predators supply prey for their young by either leaving dead prey nearby or by bringing live prey to them. Other predators, the text states, feed their young directly from their own mouths. This context supports the idea that predatory animals have various ways to provide food for their young.</p><p>Choice A is incorrect because in this context, "avoid" would mean keep away from or refrain from, neither of which would make sense in context. Nothing in the text suggests that predators refrain from food for their young. Choice B is incorrect because in this context, "guess" would mean speculate or suppose, and it&rsquo;s unclear what it would mean for predators to speculate food for their young. Choice D is incorrect because in this context, "describe" would mean explain, and it&rsquo;s unclear what it would mean for predators to explain food for their young.</p>$SATQ$, false, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, $SATQ${"questionId":"a49500cc","external_id":"f92df5e5-64e5-4ca2-90a2-cabd8a1c6b00","vaultid":null,"uId":"2fe473d7-3fdf-4d65-a890-aa5abe806fa7","program":"SAT","test_type":1,"test_type_desc":"Reading and Writing","primary_class_cd":"CAS","domain":"Craft and Structure","skill_cd":"WIC","skill_desc":"Words in Context","difficulty":"E","score_band_range_cd":1,"type":"mcq","stimulus":"<p>Predatory animals differ widely in how they <span aria-hidden=\"true\">______</span><span class=\"sr-only\">blank</span> food for their young. Some leave dead prey nearby for their young to consume, some bring live prey to their young, and some feed their young directly from their own mouths.&nbsp;</p>","stem":"<p>Which choice completes the text with the most logical and precise word or phrase?</p>","answerOptions":[{"id":"fac1e181-880d-4962-8e68-0b3c3de77eeb","content":"<p>avoid</p>"},{"id":"7b35e9a4-3d26-4ff5-be5c-36ce253a4728","content":"<p>guess</p>"},{"id":"b219fbc3-ca1f-4f08-a6bb-8a8b47915575","content":"<p>provide</p>"},{"id":"cb7fa8c8-b62d-4f7e-bb97-ce7f89164c46","content":"<p>describe</p>"}],"keys":["b219fbc3-ca1f-4f08-a6bb-8a8b47915575"],"correct_answer":["C"],"rationale":"<p>Choice C is the best answer because it most logically completes the text&rsquo;s discussion of how predators feed their young. As used in this context, \"provide\" means supply or make something that&rsquo;s needed available. The text indicates that some predators supply prey for their young by either leaving dead prey nearby or by bringing live prey to them. Other predators, the text states, feed their young directly from their own mouths. This context supports the idea that predatory animals have various ways to provide food for their young.</p><p>Choice A is incorrect because in this context, \"avoid\" would mean keep away from or refrain from, neither of which would make sense in context. Nothing in the text suggests that predators refrain from food for their young. Choice B is incorrect because in this context, \"guess\" would mean speculate or suppose, and it&rsquo;s unclear what it would mean for predators to speculate food for their young. Choice D is incorrect because in this context, \"describe\" would mean explain, and it&rsquo;s unclear what it would mean for predators to explain food for their young.</p>","parenttemplatename":null,"parenttemplateid":null,"templateclusterid":null,"templateclustername":null,"origin":null,"position":null,"createDate":1743430669215,"updateDate":1743430669215}$SATQ$::jsonb, 1743430669215, 1743430669215),
    ($SATQ$a4ca92fd$SATQ$, $SATQ$2f3c8ee3-dded-479a-9c37-f33b9d2ca2ad$SATQ$::uuid, $SATQ$71c13ce0-8dd9-4197-80a3-0b0bbe508829$SATQ$::uuid, NULL, $SATQ$qbank$SATQ$, $SATQ$SAT$SATQ$, 1, $SATQ$Reading and Writing$SATQ$, $SATQ$Craft and Structure$SATQ$, $SATQ$CAS$SATQ$, $SATQ$WIC$SATQ$, $SATQ$Words in Context$SATQ$, $SATQ$E$SATQ$, 3, $SATQ$mcq$SATQ$, $SATQ$<p>Beginning in the 1950s, Navajo Nation legislator Annie Dodge Wauneka continuously worked to promote public health; this <span aria-hidden="true">______</span><span class="sr-only">blank</span> effort involved traveling throughout the vast Navajo homeland and writing a medical dictionary for speakers of <em>Din&eacute; bizaad</em>, the Navajo language.</p>$SATQ$, $SATQ$<p>Which choice completes the text with the most logical and precise word or phrase?</p>$SATQ$, $SATQ$[{"id":"550db149-6766-492d-8c8f-f477508ab364","content":"<p>impartial</p>"},{"id":"ebbcc8d8-179d-403f-a78d-a3144ab01795","content":"<p>offhand</p>"},{"id":"35dddaa5-da03-4493-8716-84c9a3928ff5","content":"<p>persistent</p>"},{"id":"7bfe1726-d119-4bd0-a3aa-6eadc0b0bca1","content":"<p>mandatory</p>"}]$SATQ$::jsonb, $SATQ$["C"]$SATQ$::jsonb, $SATQ$["35dddaa5-da03-4493-8716-84c9a3928ff5"]$SATQ$::jsonb, $SATQ$<p>Choice C is the best answer because it most logically completes the text&rsquo;s discussion of Annie Dodge Wauneka&rsquo;s work as a Navajo Nation legislator. As used in this context, &ldquo;persistent&rdquo; means existing continuously. The text states that Wauneka &ldquo;continuously worked to promote public health,&rdquo; traveling extensively and authoring a medical dictionary; this indicates that Wauneka&rsquo;s effort was persistent. </p><p>Choice A is incorrect because describing Wauneka&rsquo;s effort related to public health as &ldquo;impartial,&rdquo; or not partial or biased and treating all things equally, wouldn&rsquo;t make sense in context. The text suggests that Wauneka&rsquo;s continuous work was partial in one way, as she focused specifically on promoting public health throughout the Navajo homeland and to speakers of the Navajo language. Choice B is incorrect because the text emphasizes that Wauneka&rsquo;s effort to promote public health as a Navajo Nation legislator was continuous and extensive, involving wide travels and the authoring of a medical dictionary. Because this work clearly involved care and dedication, it wouldn&rsquo;t make sense to describe it as &ldquo;offhand,&rdquo; or casual and informal. Choice D is incorrect because nothing in the text suggests that Wauneka&rsquo;s effort to promote public health was &ldquo;mandatory,&rdquo; or required by law or rule, even though Wauneka was a Navajo Nation legislator. Rather than suggesting that Wauneka&rsquo;s effort was required for any reason, the text emphasizes the continuous and extensive nature of her work. </p>$SATQ$, false, 0, $SATQ$OSP-936-WIC$SATQ$, $SATQ$$SATQ$, $SATQ$ee727542-9bb4-4c6b-9ce6-bf27df4af37b$SATQ$::uuid, $SATQ$$SATQ$, $SATQ$proteus$SATQ$, $SATQ$0$SATQ$, NULL, NULL, $SATQ${"questionId":"a4ca92fd","external_id":"2f3c8ee3-dded-479a-9c37-f33b9d2ca2ad","vaultid":"71c13ce0-8dd9-4197-80a3-0b0bbe508829","uId":"3d79e88e-5cc3-4655-8e7b-27d6d8ed6e19","program":"SAT","test_type":1,"test_type_desc":"Reading and Writing","primary_class_cd":"CAS","domain":"Craft and Structure","skill_cd":"WIC","skill_desc":"Words in Context","difficulty":"E","score_band_range_cd":3,"type":"mcq","stimulus":"<p>Beginning in the 1950s, Navajo Nation legislator Annie Dodge Wauneka continuously worked to promote public health; this <span aria-hidden=\"true\">______</span><span class=\"sr-only\">blank</span> effort involved traveling throughout the vast Navajo homeland and writing a medical dictionary for speakers of <em>Din&eacute; bizaad</em>, the Navajo language.</p>","stem":"<p>Which choice completes the text with the most logical and precise word or phrase?</p>","answerOptions":[{"id":"550db149-6766-492d-8c8f-f477508ab364","content":"<p>impartial</p>"},{"id":"ebbcc8d8-179d-403f-a78d-a3144ab01795","content":"<p>offhand</p>"},{"id":"35dddaa5-da03-4493-8716-84c9a3928ff5","content":"<p>persistent</p>"},{"id":"7bfe1726-d119-4bd0-a3aa-6eadc0b0bca1","content":"<p>mandatory</p>"}],"keys":["35dddaa5-da03-4493-8716-84c9a3928ff5"],"correct_answer":["C"],"rationale":"<p>Choice C is the best answer because it most logically completes the text&rsquo;s discussion of Annie Dodge Wauneka&rsquo;s work as a Navajo Nation legislator. As used in this context, &ldquo;persistent&rdquo; means existing continuously. The text states that Wauneka &ldquo;continuously worked to promote public health,&rdquo; traveling extensively and authoring a medical dictionary; this indicates that Wauneka&rsquo;s effort was persistent. </p><p>Choice A is incorrect because describing Wauneka&rsquo;s effort related to public health as &ldquo;impartial,&rdquo; or not partial or biased and treating all things equally, wouldn&rsquo;t make sense in context. The text suggests that Wauneka&rsquo;s continuous work was partial in one way, as she focused specifically on promoting public health throughout the Navajo homeland and to speakers of the Navajo language. Choice B is incorrect because the text emphasizes that Wauneka&rsquo;s effort to promote public health as a Navajo Nation legislator was continuous and extensive, involving wide travels and the authoring of a medical dictionary. Because this work clearly involved care and dedication, it wouldn&rsquo;t make sense to describe it as &ldquo;offhand,&rdquo; or casual and informal. Choice D is incorrect because nothing in the text suggests that Wauneka&rsquo;s effort to promote public health was &ldquo;mandatory,&rdquo; or required by law or rule, even though Wauneka was a Navajo Nation legislator. Rather than suggesting that Wauneka&rsquo;s effort was required for any reason, the text emphasizes the continuous and extensive nature of her work. </p>","parenttemplatename":"OSP-936-WIC","parenttemplateid":"","templateclusterid":"ee727542-9bb4-4c6b-9ce6-bf27df4af37b","templateclustername":"","origin":"proteus","position":"0","createDate":1691007959356,"updateDate":1691007959356}$SATQ$::jsonb, 1691007959356, 1691007959356),
    ($SATQ$a4f50d30$SATQ$, $SATQ$f8e1772f-9571-490e-b9a9-e0eb7b8ccb5c$SATQ$::uuid, $SATQ$a8bcbe56-1963-42c1-a759-a103af963f6e$SATQ$::uuid, NULL, $SATQ$qbank$SATQ$, $SATQ$SAT$SATQ$, 1, $SATQ$Reading and Writing$SATQ$, $SATQ$Craft and Structure$SATQ$, $SATQ$CAS$SATQ$, $SATQ$WIC$SATQ$, $SATQ$Words in Context$SATQ$, $SATQ$E$SATQ$, 2, $SATQ$mcq$SATQ$, $SATQ$<p>Scientists previously thought that all electric eels belong to a single species<em>, </em>but a team of researchers led by zoologist C. David de Santana proved this idea wrong by <span aria-hidden="true">______</span><span class="sr-only">blank</span> that there are in fact three distinct species of electric eels.&nbsp;</p>$SATQ$, $SATQ$<p>Which choice completes the text with the most logical and precise word or phrase?</p>$SATQ$, $SATQ$[{"id":"8f58bee0-33bc-40f8-8b1f-97d49e83fc67","content":"<p>pretending</p>"},{"id":"91397670-7b3f-4e24-b109-c786b38a6df8","content":"<p>complaining</p>"},{"id":"0332aee1-dba3-4ee4-8782-38a5df737f12","content":"<p>requiring</p>"},{"id":"69f50985-14e9-458a-9d16-3969096241e3","content":"<p>demonstrating</p>"}]$SATQ$::jsonb, $SATQ$["D"]$SATQ$::jsonb, $SATQ$["69f50985-14e9-458a-9d16-3969096241e3"]$SATQ$::jsonb, $SATQ$<p>Choice D is the best answer. &ldquo;Demonstrating&rdquo; means &ldquo;showing,&rdquo; and the text describes how de Santana disproved a previous belief in only one species of electric eel by showing that three electric eel species actually exist. </p><p>Choice A is incorrect. Pretending that there are three species of electric eel might be a fun game for marine biologists, but it wouldn&rsquo;t prove the existence of more than one species. Choice B is incorrect. Complaining won&rsquo;t prove anything about eels, so de Santana could not have proved wrong the idea of only one species of electric eel by complaining about it. Choice C is incorrect. &ldquo;Requiring&rdquo; means &ldquo;needing.&rdquo; It wouldn&rsquo;t make sense to say that de Santana &ldquo;needed&rdquo; there to be three distinct species of electric eel. </p>$SATQ$, false, 0, $SATQ$OSP-KA-WIC-E010$SATQ$, $SATQ$$SATQ$, $SATQ$1fee3825-1664-4908-a956-d6138816438d$SATQ$::uuid, $SATQ$$SATQ$, $SATQ$proteus$SATQ$, $SATQ$0$SATQ$, NULL, NULL, $SATQ${"questionId":"a4f50d30","external_id":"f8e1772f-9571-490e-b9a9-e0eb7b8ccb5c","vaultid":"a8bcbe56-1963-42c1-a759-a103af963f6e","uId":"a9b3fc8d-f43c-4f94-9efc-ec7508eed0f7","program":"SAT","test_type":1,"test_type_desc":"Reading and Writing","primary_class_cd":"CAS","domain":"Craft and Structure","skill_cd":"WIC","skill_desc":"Words in Context","difficulty":"E","score_band_range_cd":2,"type":"mcq","stimulus":"<p>Scientists previously thought that all electric eels belong to a single species<em>, </em>but a team of researchers led by zoologist C. David de Santana proved this idea wrong by <span aria-hidden=\"true\">______</span><span class=\"sr-only\">blank</span> that there are in fact three distinct species of electric eels.&nbsp;</p>","stem":"<p>Which choice completes the text with the most logical and precise word or phrase?</p>","answerOptions":[{"id":"8f58bee0-33bc-40f8-8b1f-97d49e83fc67","content":"<p>pretending</p>"},{"id":"91397670-7b3f-4e24-b109-c786b38a6df8","content":"<p>complaining</p>"},{"id":"0332aee1-dba3-4ee4-8782-38a5df737f12","content":"<p>requiring</p>"},{"id":"69f50985-14e9-458a-9d16-3969096241e3","content":"<p>demonstrating</p>"}],"keys":["69f50985-14e9-458a-9d16-3969096241e3"],"correct_answer":["D"],"rationale":"<p>Choice D is the best answer. &ldquo;Demonstrating&rdquo; means &ldquo;showing,&rdquo; and the text describes how de Santana disproved a previous belief in only one species of electric eel by showing that three electric eel species actually exist. </p><p>Choice A is incorrect. Pretending that there are three species of electric eel might be a fun game for marine biologists, but it wouldn&rsquo;t prove the existence of more than one species. Choice B is incorrect. Complaining won&rsquo;t prove anything about eels, so de Santana could not have proved wrong the idea of only one species of electric eel by complaining about it. Choice C is incorrect. &ldquo;Requiring&rdquo; means &ldquo;needing.&rdquo; It wouldn&rsquo;t make sense to say that de Santana &ldquo;needed&rdquo; there to be three distinct species of electric eel. </p>","parenttemplatename":"OSP-KA-WIC-E010","parenttemplateid":"","templateclusterid":"1fee3825-1664-4908-a956-d6138816438d","templateclustername":"","origin":"proteus","position":"0","createDate":1691007959377,"updateDate":1691007959377}$SATQ$::jsonb, 1691007959377, 1691007959377),
    ($SATQ$a5e747f0$SATQ$, $SATQ$fa690c59-b7d8-42c6-9e63-de35fb8e9ed8$SATQ$::uuid, NULL, NULL, $SATQ$qbank$SATQ$, $SATQ$SAT$SATQ$, 1, $SATQ$Reading and Writing$SATQ$, $SATQ$Craft and Structure$SATQ$, $SATQ$CAS$SATQ$, $SATQ$WIC$SATQ$, $SATQ$Words in Context$SATQ$, $SATQ$H$SATQ$, 7, $SATQ$mcq$SATQ$, $SATQ$<p>Despite how <span aria-hidden="true">______</span><span class="sr-only">blank</span> they may seem on first glance, the works of the philosopher Georg Hegel have proven to be quite influential. Readers who manage to penetrate Hegel&rsquo;s frustratingly dense prose often find that his thrillingly original and profound ideas wind up shaping their own thinking.</p>$SATQ$, $SATQ$<p>Which choice completes the text with the most logical and precise word or phrase?</p>$SATQ$, $SATQ$[{"id":"1b620994-fe74-43b8-913a-daca93bbf9ef","content":"<p>authoritative</p>"},{"id":"c5574b1b-91e7-4ba6-9ffb-544f0c0cc9d0","content":"<p>opaque</p>"},{"id":"396f9794-8d22-4d67-84fa-14f274a0bf91","content":"<p>empirical</p>"},{"id":"171f3f30-aceb-4fbb-bff0-f5d034fdf718","content":"<p>facile</p>"}]$SATQ$::jsonb, $SATQ$["B"]$SATQ$::jsonb, $SATQ$["c5574b1b-91e7-4ba6-9ffb-544f0c0cc9d0"]$SATQ$::jsonb, $SATQ$<p>Choice B is the best answer because it most logically completes the text&rsquo;s discussion of Hegel&rsquo;s works. In this context, "opaque" means difficult to understand or unclear. The text creates a contrast between the initial impression given by Hegel&rsquo;s works and their influence and insight, noting that readers must "penetrate Hegel&rsquo;s frustratingly dense prose" to access his important ideas. This context clearly establishes that Hegel&rsquo;s writing is initially challenging to comprehend, or opaque.</p><p>Choice A is incorrect because "authoritative" means influential or clearly accurate. Hegel&rsquo;s works may be authoritative, but it wouldn&rsquo;t make logical sense in context to say that although his works seem authoritative, they have been influential. Instead, the text focuses on the fact that Hegel&rsquo;s works are challenging to read, but that working through the dense prose can be rewarding. Choice C is incorrect because referring to Hegel&rsquo;s works as "empirical," which means factual or verifiable, would suggest that they are based on observation or experience rather than theory. The text, however, doesn&rsquo;t address this aspect of Hegel&rsquo;s philosophy. Instead, it focuses on the difficulty of understanding his writing. Choice D is incorrect because describing Hegel&rsquo;s works as "facile," which means superficial or simplistic, would directly contradict the text&rsquo;s characterization of his writing as "frustratingly dense" and requiring effort to understand.</p>$SATQ$, false, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, $SATQ${"questionId":"a5e747f0","external_id":"fa690c59-b7d8-42c6-9e63-de35fb8e9ed8","vaultid":null,"uId":"9b373698-d114-43cb-b8a6-d95952536515","program":"SAT","test_type":1,"test_type_desc":"Reading and Writing","primary_class_cd":"CAS","domain":"Craft and Structure","skill_cd":"WIC","skill_desc":"Words in Context","difficulty":"H","score_band_range_cd":7,"type":"mcq","stimulus":"<p>Despite how <span aria-hidden=\"true\">______</span><span class=\"sr-only\">blank</span> they may seem on first glance, the works of the philosopher Georg Hegel have proven to be quite influential. Readers who manage to penetrate Hegel&rsquo;s frustratingly dense prose often find that his thrillingly original and profound ideas wind up shaping their own thinking.</p>","stem":"<p>Which choice completes the text with the most logical and precise word or phrase?</p>","answerOptions":[{"id":"1b620994-fe74-43b8-913a-daca93bbf9ef","content":"<p>authoritative</p>"},{"id":"c5574b1b-91e7-4ba6-9ffb-544f0c0cc9d0","content":"<p>opaque</p>"},{"id":"396f9794-8d22-4d67-84fa-14f274a0bf91","content":"<p>empirical</p>"},{"id":"171f3f30-aceb-4fbb-bff0-f5d034fdf718","content":"<p>facile</p>"}],"keys":["c5574b1b-91e7-4ba6-9ffb-544f0c0cc9d0"],"correct_answer":["B"],"rationale":"<p>Choice B is the best answer because it most logically completes the text&rsquo;s discussion of Hegel&rsquo;s works. In this context, \"opaque\" means difficult to understand or unclear. The text creates a contrast between the initial impression given by Hegel&rsquo;s works and their influence and insight, noting that readers must \"penetrate Hegel&rsquo;s frustratingly dense prose\" to access his important ideas. This context clearly establishes that Hegel&rsquo;s writing is initially challenging to comprehend, or opaque.</p><p>Choice A is incorrect because \"authoritative\" means influential or clearly accurate. Hegel&rsquo;s works may be authoritative, but it wouldn&rsquo;t make logical sense in context to say that although his works seem authoritative, they have been influential. Instead, the text focuses on the fact that Hegel&rsquo;s works are challenging to read, but that working through the dense prose can be rewarding. Choice C is incorrect because referring to Hegel&rsquo;s works as \"empirical,\" which means factual or verifiable, would suggest that they are based on observation or experience rather than theory. The text, however, doesn&rsquo;t address this aspect of Hegel&rsquo;s philosophy. Instead, it focuses on the difficulty of understanding his writing. Choice D is incorrect because describing Hegel&rsquo;s works as \"facile,\" which means superficial or simplistic, would directly contradict the text&rsquo;s characterization of his writing as \"frustratingly dense\" and requiring effort to understand.</p>","parenttemplatename":null,"parenttemplateid":null,"templateclusterid":null,"templateclustername":null,"origin":null,"position":null,"createDate":1755117061193,"updateDate":1755117061193}$SATQ$::jsonb, 1755117061193, 1755117061193),
    ($SATQ$a60b0004$SATQ$, $SATQ$62f1d2d5-5df8-4338-925f-1fae85ea6f74$SATQ$::uuid, $SATQ$256a06e5-3f79-4921-9216-38051978dfda$SATQ$::uuid, NULL, $SATQ$qbank$SATQ$, $SATQ$SAT$SATQ$, 1, $SATQ$Reading and Writing$SATQ$, $SATQ$Craft and Structure$SATQ$, $SATQ$CAS$SATQ$, $SATQ$WIC$SATQ$, $SATQ$Words in Context$SATQ$, $SATQ$H$SATQ$, 6, $SATQ$mcq$SATQ$, $SATQ$<p>Scholarly discussions of gender in Shakespeare&rsquo;s comedies often celebrate the rebellion of the playwright&rsquo;s characters against the rigid expectations <span aria-hidden="true">______</span><span class="sr-only">blank</span> by Elizabethan society. Most of the comedies end in marriage, with characters returning to their socially dictated gender roles after previously defying them, but there are some notable exceptions.</p>$SATQ$, $SATQ$<p>Which choice completes the text with the most logical and precise word or phrase?</p>$SATQ$, $SATQ$[{"id":"db74149f-334a-434b-9bf7-90b937e07ecd","content":"<p>interjected</p>"},{"id":"7840e5ee-0180-4856-80ef-1e4f1cc8a92e","content":"<p>committed</p>"},{"id":"2922878f-41d5-487e-9fb6-5ce4b9c9f585","content":"<p>illustrated</p>"},{"id":"3b8fb0a5-09d6-49c6-babb-430916486285","content":"<p>prescribed</p>"}]$SATQ$::jsonb, $SATQ$["D"]$SATQ$::jsonb, $SATQ$["3b8fb0a5-09d6-49c6-babb-430916486285"]$SATQ$::jsonb, $SATQ$<p>Choice D is the best answer because it most logically completes the text&rsquo;s discussion of gender roles in Shakespeare&rsquo;s comedies. As used in this context, &ldquo;prescribed&rdquo; would mean laid down as rules. The text indicates that the characters in the comedies often defy gender roles that are &ldquo;socially dictated&rdquo; (even if most characters do return to those roles eventually) and that scholars have been very interested in these acts of defiance. This context indicates that what the characters are rebelling against are standards of behavior prescribed by the society of the time.&nbsp;&nbsp;</p><p>Choice A is incorrect because saying that expectations about gender were &ldquo;interjected,&rdquo; or suddenly inserted between other things, wouldn&rsquo;t make sense in context. There&rsquo;s no suggestion in the text that the issue of gender roles was inserted between other things or was an interruption in a larger discussion.&nbsp;Choice B is incorrect because the text indicates that Shakespeare depicts characters rebelling against expectations about gender that have been &ldquo;socially dictated,&rdquo; not expectations that society has &ldquo;committed,&rdquo; or carried out, entrusted, or promised. Choice C is incorrect because the text indicates that Shakespeare depicts characters rebelling against expectations about gender that have been &ldquo;socially dictated,&rdquo; not expectations that have been &ldquo;illustrated,&rdquo; or clarified with examples. Although it&rsquo;s possible for expectations about gender roles to be illustrated, there&rsquo;s nothing in the text to indicate that characters in Shakespeare&rsquo;s comedies rebel against illustrations of gender expectations. </p>$SATQ$, false, 0, $SATQ$OSP-975-WIC$SATQ$, $SATQ$$SATQ$, $SATQ$2698c8f4-8e7b-43d4-a5d7-8891d99a878f$SATQ$::uuid, $SATQ$$SATQ$, $SATQ$proteus$SATQ$, $SATQ$0$SATQ$, NULL, NULL, $SATQ${"questionId":"a60b0004","external_id":"62f1d2d5-5df8-4338-925f-1fae85ea6f74","vaultid":"256a06e5-3f79-4921-9216-38051978dfda","uId":"9a0568f3-efdc-48f6-9b2d-b78172802ccc","program":"SAT","test_type":1,"test_type_desc":"Reading and Writing","primary_class_cd":"CAS","domain":"Craft and Structure","skill_cd":"WIC","skill_desc":"Words in Context","difficulty":"H","score_band_range_cd":6,"type":"mcq","stimulus":"<p>Scholarly discussions of gender in Shakespeare&rsquo;s comedies often celebrate the rebellion of the playwright&rsquo;s characters against the rigid expectations <span aria-hidden=\"true\">______</span><span class=\"sr-only\">blank</span> by Elizabethan society. Most of the comedies end in marriage, with characters returning to their socially dictated gender roles after previously defying them, but there are some notable exceptions.</p>","stem":"<p>Which choice completes the text with the most logical and precise word or phrase?</p>","answerOptions":[{"id":"db74149f-334a-434b-9bf7-90b937e07ecd","content":"<p>interjected</p>"},{"id":"7840e5ee-0180-4856-80ef-1e4f1cc8a92e","content":"<p>committed</p>"},{"id":"2922878f-41d5-487e-9fb6-5ce4b9c9f585","content":"<p>illustrated</p>"},{"id":"3b8fb0a5-09d6-49c6-babb-430916486285","content":"<p>prescribed</p>"}],"keys":["3b8fb0a5-09d6-49c6-babb-430916486285"],"correct_answer":["D"],"rationale":"<p>Choice D is the best answer because it most logically completes the text&rsquo;s discussion of gender roles in Shakespeare&rsquo;s comedies. As used in this context, &ldquo;prescribed&rdquo; would mean laid down as rules. The text indicates that the characters in the comedies often defy gender roles that are &ldquo;socially dictated&rdquo; (even if most characters do return to those roles eventually) and that scholars have been very interested in these acts of defiance. This context indicates that what the characters are rebelling against are standards of behavior prescribed by the society of the time.&nbsp;&nbsp;</p><p>Choice A is incorrect because saying that expectations about gender were &ldquo;interjected,&rdquo; or suddenly inserted between other things, wouldn&rsquo;t make sense in context. There&rsquo;s no suggestion in the text that the issue of gender roles was inserted between other things or was an interruption in a larger discussion.&nbsp;Choice B is incorrect because the text indicates that Shakespeare depicts characters rebelling against expectations about gender that have been &ldquo;socially dictated,&rdquo; not expectations that society has &ldquo;committed,&rdquo; or carried out, entrusted, or promised. Choice C is incorrect because the text indicates that Shakespeare depicts characters rebelling against expectations about gender that have been &ldquo;socially dictated,&rdquo; not expectations that have been &ldquo;illustrated,&rdquo; or clarified with examples. Although it&rsquo;s possible for expectations about gender roles to be illustrated, there&rsquo;s nothing in the text to indicate that characters in Shakespeare&rsquo;s comedies rebel against illustrations of gender expectations. </p>","parenttemplatename":"OSP-975-WIC","parenttemplateid":"","templateclusterid":"2698c8f4-8e7b-43d4-a5d7-8891d99a878f","templateclustername":"","origin":"proteus","position":"0","createDate":1691007959357,"updateDate":1691007959357}$SATQ$::jsonb, 1691007959357, 1691007959357),
    ($SATQ$a68239ed$SATQ$, $SATQ$0c915748-3254-47e8-a2e0-e245099b3dfd$SATQ$::uuid, $SATQ$792b45dd-58be-4b63-bd76-d0c73aeecc1f$SATQ$::uuid, NULL, $SATQ$qbank$SATQ$, $SATQ$SAT$SATQ$, 1, $SATQ$Reading and Writing$SATQ$, $SATQ$Craft and Structure$SATQ$, $SATQ$CAS$SATQ$, $SATQ$TSP$SATQ$, $SATQ$Text Structure and Purpose$SATQ$, $SATQ$E$SATQ$, 3, $SATQ$mcq$SATQ$, $SATQ$<p>The following text is adapted from Oscar Wilde&rsquo;s 1897 nonfiction work <em>De Profundis</em>.&nbsp;</p>
<blockquote>
<p>People whose desire is solely for self-realisation never know where they are going. They can&rsquo;t know. In one sense of the word it is of course necessary to know oneself: that is the first achievement of knowledge. But to recognise that the soul of a man is unknowable, is the ultimate achievement of wisdom. The final mystery is oneself. When one has weighed the sun in the balance, and measured the steps of the moon, and mapped out the seven heavens star by star, there still remains oneself. <span role="region" aria-label="Referenced Content"><u>Who can calculate the orbit of his own soul?</u></span></p>
</blockquote>$SATQ$, $SATQ$<p>Which choice best describes the function of the underlined question in the text as a whole?</p>$SATQ$, $SATQ$[{"id":"ead6c109-966c-4560-8597-220c0e83defa","content":"<p>It reinforces the text&rsquo;s skepticism about the possibility of truly achieving self-knowledge.</p>"},{"id":"febc2246-00d9-475d-85ad-8e69162a2a4c","content":"<p>It speculates that some readers will share the doubts expressed in the text about the value of self-knowledge.</p>"},{"id":"f0bb4cde-e594-4fa8-80c3-7b3ca83f7aeb","content":"<p>It cautions readers that the text&rsquo;s directions for how to achieve self-knowledge are hard to follow.</p>"},{"id":"a05347cd-212f-45cf-9f1c-d2be801be0b8","content":"<p>It concedes that the definition of self-knowledge advanced in the text is unpopular.</p>"}]$SATQ$::jsonb, $SATQ$["A"]$SATQ$::jsonb, $SATQ$["ead6c109-966c-4560-8597-220c0e83defa"]$SATQ$::jsonb, $SATQ$<p>Choice A is the best answer. The text repeatedly claims that true self-knowledge can&rsquo;t possibly be achieved, and this rhetorical question emphasizes that point. </p><p>Choice B is incorrect. The underlined question doesn&rsquo;t do this. The text never expresses doubts about the value of self-knowledge&mdash;rather, the text expresses doubts about the possibility of achieving self-knowledge. Choice C is incorrect. The underlined question doesn&rsquo;t do this. The text doesn&rsquo;t provide directions for how to achieve self-knowledge&mdash;rather, it claims that true self-knowledge is impossible to achieve. Choice D is incorrect. The underlined question doesn&rsquo;t do this. The text doesn&rsquo;t ever define self-knowledge, and popularity isn&rsquo;t mentioned in the text at all. </p>$SATQ$, false, 0, $SATQ$OSP-KA-TSP-M001$SATQ$, $SATQ$$SATQ$, $SATQ$5a03312f-0565-4584-bb31-6becb61aa2bf$SATQ$::uuid, $SATQ$$SATQ$, $SATQ$proteus$SATQ$, $SATQ$0$SATQ$, NULL, NULL, $SATQ${"questionId":"a68239ed","external_id":"0c915748-3254-47e8-a2e0-e245099b3dfd","vaultid":"792b45dd-58be-4b63-bd76-d0c73aeecc1f","uId":"78b449b0-524f-4f61-b288-843feac3cd05","program":"SAT","test_type":1,"test_type_desc":"Reading and Writing","primary_class_cd":"CAS","domain":"Craft and Structure","skill_cd":"TSP","skill_desc":"Text Structure and Purpose","difficulty":"E","score_band_range_cd":3,"type":"mcq","stimulus":"<p>The following text is adapted from Oscar Wilde&rsquo;s 1897 nonfiction work <em>De Profundis</em>.&nbsp;</p>\n<blockquote>\n<p>People whose desire is solely for self-realisation never know where they are going. They can&rsquo;t know. In one sense of the word it is of course necessary to know oneself: that is the first achievement of knowledge. But to recognise that the soul of a man is unknowable, is the ultimate achievement of wisdom. The final mystery is oneself. When one has weighed the sun in the balance, and measured the steps of the moon, and mapped out the seven heavens star by star, there still remains oneself. <span role=\"region\" aria-label=\"Referenced Content\"><u>Who can calculate the orbit of his own soul?</u></span></p>\n</blockquote>","stem":"<p>Which choice best describes the function of the underlined question in the text as a whole?</p>","answerOptions":[{"id":"ead6c109-966c-4560-8597-220c0e83defa","content":"<p>It reinforces the text&rsquo;s skepticism about the possibility of truly achieving self-knowledge.</p>"},{"id":"febc2246-00d9-475d-85ad-8e69162a2a4c","content":"<p>It speculates that some readers will share the doubts expressed in the text about the value of self-knowledge.</p>"},{"id":"f0bb4cde-e594-4fa8-80c3-7b3ca83f7aeb","content":"<p>It cautions readers that the text&rsquo;s directions for how to achieve self-knowledge are hard to follow.</p>"},{"id":"a05347cd-212f-45cf-9f1c-d2be801be0b8","content":"<p>It concedes that the definition of self-knowledge advanced in the text is unpopular.</p>"}],"keys":["ead6c109-966c-4560-8597-220c0e83defa"],"correct_answer":["A"],"rationale":"<p>Choice A is the best answer. The text repeatedly claims that true self-knowledge can&rsquo;t possibly be achieved, and this rhetorical question emphasizes that point. </p><p>Choice B is incorrect. The underlined question doesn&rsquo;t do this. The text never expresses doubts about the value of self-knowledge&mdash;rather, the text expresses doubts about the possibility of achieving self-knowledge. Choice C is incorrect. The underlined question doesn&rsquo;t do this. The text doesn&rsquo;t provide directions for how to achieve self-knowledge&mdash;rather, it claims that true self-knowledge is impossible to achieve. Choice D is incorrect. The underlined question doesn&rsquo;t do this. The text doesn&rsquo;t ever define self-knowledge, and popularity isn&rsquo;t mentioned in the text at all. </p>","parenttemplatename":"OSP-KA-TSP-M001","parenttemplateid":"","templateclusterid":"5a03312f-0565-4584-bb31-6becb61aa2bf","templateclustername":"","origin":"proteus","position":"0","createDate":1691007959375,"updateDate":1691007959375}$SATQ$::jsonb, 1691007959375, 1691007959375),
    ($SATQ$a70cbc53$SATQ$, $SATQ$eb41fdd8-5221-4465-89b4-84796c6e4441$SATQ$::uuid, $SATQ$a98a96ff-f243-4ee7-9de0-26c6c029cf3d$SATQ$::uuid, NULL, $SATQ$qbank$SATQ$, $SATQ$SAT$SATQ$, 1, $SATQ$Reading and Writing$SATQ$, $SATQ$Craft and Structure$SATQ$, $SATQ$CAS$SATQ$, $SATQ$TSP$SATQ$, $SATQ$Text Structure and Purpose$SATQ$, $SATQ$H$SATQ$, 6, $SATQ$mcq$SATQ$, $SATQ$<p>Raymond Antrobus, an accomplished poet and writer of prose, recently released his debut spoken word poetry album, <em>The First Time I Wore Hearing Aids</em>, in collaboration with producer Ian Brennan. The album contains both autobiographical and reflective pieces combining Antrobus&rsquo;s spoken words with Brennan&rsquo;s fragmented audio elements and pieces of music to convey how people who are deaf may experience sound, both its presence and absence. Some critics suggest that the album questions the function of sound in the world, highlighting that the experience of sound is multifaceted.</p>$SATQ$, $SATQ$<p>Which choice best describes the overall structure of the text?</p>$SATQ$, $SATQ$[{"id":"8c5a9cab-e39f-458c-a616-5fd6cc8b035f","content":"<p>It introduces a collaborative spoken word poetry project, details the approach taken to produce the work, and then provides an example of critique the album received upon release.&nbsp;</p>"},{"id":"7b100a5f-7709-431d-b016-b46373ec0a99","content":"<p>It mentions a collection of spoken word poems, distinguishes one poem as being an exemplar on the album, and then offers a summary of the subject matter of the whole collection.</p>"},{"id":"e7d27a4d-78a8-4412-96d9-56614d4f5019","content":"<p>It summarizes the efforts to produce a collection of spoken word poems, presents biographies of two people who worked on the album, and speculates about the meaning behind the poetry.</p>"},{"id":"4e560a27-e65a-4858-b086-d7036fc05761","content":"<p>It connects two artists to the same spoken word poetry project, explains the extent of their collaboration on each poem, and then provides an overview of the technique used to produce the work.</p>"}]$SATQ$::jsonb, $SATQ$["A"]$SATQ$::jsonb, $SATQ$["8c5a9cab-e39f-458c-a616-5fd6cc8b035f"]$SATQ$::jsonb, $SATQ$<p>Choice A is the best answer. The text first introduces the album as being a collaboration between Antrobus and Brennan, then describes the approach taken to produce it, then mentions how critics have said that it calls into question the function of sound. </p><p>Choice B is incorrect. While the text does mention a collection of spoken word poems, it doesn&rsquo;t single out one poem as being particularly noteworthy. Additionally, the text doesn&rsquo;t simply summarize the subject matter&mdash;it goes into detail about the content and production of the album. Choice C is incorrect. The text doesn&rsquo;t provide biographical information about the two artists, and the text doesn&rsquo;t speculate about the meaning behind the poetry&mdash;instead, it relays what some critics have said about the album. Choice D is incorrect. The text doesn&rsquo;t provide just an overview of the production techniques used but instead goes into more detail about the content and audio elements of the album, as well as critical response to the album. </p>$SATQ$, false, 0, $SATQ$OSP-KA-TSP-H006$SATQ$, $SATQ$$SATQ$, $SATQ$8170030e-cef1-452c-9e5b-80b4a465bab3$SATQ$::uuid, $SATQ$$SATQ$, $SATQ$proteus$SATQ$, $SATQ$0$SATQ$, NULL, NULL, $SATQ${"questionId":"a70cbc53","external_id":"eb41fdd8-5221-4465-89b4-84796c6e4441","vaultid":"a98a96ff-f243-4ee7-9de0-26c6c029cf3d","uId":"bbc2f30a-29db-4ab7-9560-db3564f5c92b","program":"SAT","test_type":1,"test_type_desc":"Reading and Writing","primary_class_cd":"CAS","domain":"Craft and Structure","skill_cd":"TSP","skill_desc":"Text Structure and Purpose","difficulty":"H","score_band_range_cd":6,"type":"mcq","stimulus":"<p>Raymond Antrobus, an accomplished poet and writer of prose, recently released his debut spoken word poetry album, <em>The First Time I Wore Hearing Aids</em>, in collaboration with producer Ian Brennan. The album contains both autobiographical and reflective pieces combining Antrobus&rsquo;s spoken words with Brennan&rsquo;s fragmented audio elements and pieces of music to convey how people who are deaf may experience sound, both its presence and absence. Some critics suggest that the album questions the function of sound in the world, highlighting that the experience of sound is multifaceted.</p>","stem":"<p>Which choice best describes the overall structure of the text?</p>","answerOptions":[{"id":"8c5a9cab-e39f-458c-a616-5fd6cc8b035f","content":"<p>It introduces a collaborative spoken word poetry project, details the approach taken to produce the work, and then provides an example of critique the album received upon release.&nbsp;</p>"},{"id":"7b100a5f-7709-431d-b016-b46373ec0a99","content":"<p>It mentions a collection of spoken word poems, distinguishes one poem as being an exemplar on the album, and then offers a summary of the subject matter of the whole collection.</p>"},{"id":"e7d27a4d-78a8-4412-96d9-56614d4f5019","content":"<p>It summarizes the efforts to produce a collection of spoken word poems, presents biographies of two people who worked on the album, and speculates about the meaning behind the poetry.</p>"},{"id":"4e560a27-e65a-4858-b086-d7036fc05761","content":"<p>It connects two artists to the same spoken word poetry project, explains the extent of their collaboration on each poem, and then provides an overview of the technique used to produce the work.</p>"}],"keys":["8c5a9cab-e39f-458c-a616-5fd6cc8b035f"],"correct_answer":["A"],"rationale":"<p>Choice A is the best answer. The text first introduces the album as being a collaboration between Antrobus and Brennan, then describes the approach taken to produce it, then mentions how critics have said that it calls into question the function of sound. </p><p>Choice B is incorrect. While the text does mention a collection of spoken word poems, it doesn&rsquo;t single out one poem as being particularly noteworthy. Additionally, the text doesn&rsquo;t simply summarize the subject matter&mdash;it goes into detail about the content and production of the album. Choice C is incorrect. The text doesn&rsquo;t provide biographical information about the two artists, and the text doesn&rsquo;t speculate about the meaning behind the poetry&mdash;instead, it relays what some critics have said about the album. Choice D is incorrect. The text doesn&rsquo;t provide just an overview of the production techniques used but instead goes into more detail about the content and audio elements of the album, as well as critical response to the album. </p>","parenttemplatename":"OSP-KA-TSP-H006","parenttemplateid":"","templateclusterid":"8170030e-cef1-452c-9e5b-80b4a465bab3","templateclustername":"","origin":"proteus","position":"0","createDate":1691007959375,"updateDate":1691007959375}$SATQ$::jsonb, 1691007959375, 1691007959375),
    ($SATQ$a756aa95$SATQ$, $SATQ$773e98b5-c08a-40e3-b4c1-5329396dc685$SATQ$::uuid, $SATQ$f8ae4211-fb32-4c7c-9e1e-255e969cbd57$SATQ$::uuid, NULL, $SATQ$qbank$SATQ$, $SATQ$SAT$SATQ$, 1, $SATQ$Reading and Writing$SATQ$, $SATQ$Craft and Structure$SATQ$, $SATQ$CAS$SATQ$, $SATQ$WIC$SATQ$, $SATQ$Words in Context$SATQ$, $SATQ$H$SATQ$, 7, $SATQ$mcq$SATQ$, $SATQ$<p>The province of Xoconochco was situated on the Pacific coast, hundreds of kilometers southeast of Tenochtitlan, the capital of the Aztec Empire. Because Xoconochco&rsquo;s location within the empire was so <span aria-hidden="true">______</span><span class="sr-only">blank</span>, cacao and other trade goods produced there could reach the capital only after a long overland journey.</p>$SATQ$, $SATQ$<p>Which choice completes the text with the most logical and precise word or phrase?</p>$SATQ$, $SATQ$[{"id":"ee0d9d4b-3203-4c90-a9a5-31549ad6ca9f","content":"<p>unobtrusive</p>"},{"id":"1c8388ff-0f89-4a80-a8f8-5fcad6cb2a88","content":"<p>concealed</p>"},{"id":"0aabf40b-3514-42b2-a1f6-07d3f4952c9e","content":"<p>approximate</p>"},{"id":"8d1d421d-b296-49b3-9143-dc62aedc89e1","content":"<p>peripheral</p>"}]$SATQ$::jsonb, $SATQ$["D"]$SATQ$::jsonb, $SATQ$["8d1d421d-b296-49b3-9143-dc62aedc89e1"]$SATQ$::jsonb, $SATQ$<p>Choice D is the best answer because it most logically completes the text&rsquo;s discussion of the location of the province of Xoconochco within the Aztec Empire. As used in this context, &ldquo;peripheral&rdquo; means situated toward the outer bounds rather than the center. The text indicates that Xoconochco was located on a coast, hundreds of kilometers away from the capital of the Aztec Empire. The text also states that trade between the province and the capital required &ldquo;a long overland journey.&rdquo; This context suggests that Xoconochco was situated toward an edge of the empire&rsquo;s territory rather than near its center. </p><p>Choice A is incorrect because it wouldn&rsquo;t make sense in context to refer to Xoconochco&rsquo;s location within the Aztec Empire as &ldquo;unobtrusive,&rdquo; or not blatant or undesirably prominent; it&rsquo;s not clear how a province&rsquo;s physical location would or wouldn&rsquo;t be blatant. Instead of focusing on how noticeable Xoconochco&rsquo;s location was, the text emphasizes the province&rsquo;s distance from the capital of the empire, pointing out that because of this distance trade between the two required &ldquo;a long overland journey.&rdquo; Choice B is incorrect because the text indicates that the province of Xoconochco was located on a coast far from the capital of the Aztec Empire, not that it was &ldquo;concealed,&rdquo; or kept out of sight or hidden from view. Nothing in the text suggests that Xoconochco was actually hidden such that people couldn&rsquo;t see it, and being hidden wouldn&rsquo;t necessarily result in trade between the province and the capital requiring &ldquo;a long overland journey.&rdquo; Choice C is incorrect because to say that Xoconochco&rsquo;s location within the Aztec Empire was &ldquo;approximate&rdquo; would mean that the location either wasn&rsquo;t precisely correct or was close to some other location. Neither of these meanings would make sense in context because the text indicates that Xoconochco&rsquo;s location is known and that it was far from the empire&rsquo;s capital, so there&rsquo;s no reason to characterize the location as either not precisely correct or close to another location. </p>$SATQ$, false, 0, $SATQ$OSP-945-WIC$SATQ$, $SATQ$$SATQ$, $SATQ$6144c2d2-6f14-42c6-a9c4-6371964209d5$SATQ$::uuid, $SATQ$$SATQ$, $SATQ$proteus$SATQ$, $SATQ$0$SATQ$, NULL, NULL, $SATQ${"questionId":"a756aa95","external_id":"773e98b5-c08a-40e3-b4c1-5329396dc685","vaultid":"f8ae4211-fb32-4c7c-9e1e-255e969cbd57","uId":"f33ffb1c-68ca-4deb-8868-f44d212d19ef","program":"SAT","test_type":1,"test_type_desc":"Reading and Writing","primary_class_cd":"CAS","domain":"Craft and Structure","skill_cd":"WIC","skill_desc":"Words in Context","difficulty":"H","score_band_range_cd":7,"type":"mcq","stimulus":"<p>The province of Xoconochco was situated on the Pacific coast, hundreds of kilometers southeast of Tenochtitlan, the capital of the Aztec Empire. Because Xoconochco&rsquo;s location within the empire was so <span aria-hidden=\"true\">______</span><span class=\"sr-only\">blank</span>, cacao and other trade goods produced there could reach the capital only after a long overland journey.</p>","stem":"<p>Which choice completes the text with the most logical and precise word or phrase?</p>","answerOptions":[{"id":"ee0d9d4b-3203-4c90-a9a5-31549ad6ca9f","content":"<p>unobtrusive</p>"},{"id":"1c8388ff-0f89-4a80-a8f8-5fcad6cb2a88","content":"<p>concealed</p>"},{"id":"0aabf40b-3514-42b2-a1f6-07d3f4952c9e","content":"<p>approximate</p>"},{"id":"8d1d421d-b296-49b3-9143-dc62aedc89e1","content":"<p>peripheral</p>"}],"keys":["8d1d421d-b296-49b3-9143-dc62aedc89e1"],"correct_answer":["D"],"rationale":"<p>Choice D is the best answer because it most logically completes the text&rsquo;s discussion of the location of the province of Xoconochco within the Aztec Empire. As used in this context, &ldquo;peripheral&rdquo; means situated toward the outer bounds rather than the center. The text indicates that Xoconochco was located on a coast, hundreds of kilometers away from the capital of the Aztec Empire. The text also states that trade between the province and the capital required &ldquo;a long overland journey.&rdquo; This context suggests that Xoconochco was situated toward an edge of the empire&rsquo;s territory rather than near its center. </p><p>Choice A is incorrect because it wouldn&rsquo;t make sense in context to refer to Xoconochco&rsquo;s location within the Aztec Empire as &ldquo;unobtrusive,&rdquo; or not blatant or undesirably prominent; it&rsquo;s not clear how a province&rsquo;s physical location would or wouldn&rsquo;t be blatant. Instead of focusing on how noticeable Xoconochco&rsquo;s location was, the text emphasizes the province&rsquo;s distance from the capital of the empire, pointing out that because of this distance trade between the two required &ldquo;a long overland journey.&rdquo; Choice B is incorrect because the text indicates that the province of Xoconochco was located on a coast far from the capital of the Aztec Empire, not that it was &ldquo;concealed,&rdquo; or kept out of sight or hidden from view. Nothing in the text suggests that Xoconochco was actually hidden such that people couldn&rsquo;t see it, and being hidden wouldn&rsquo;t necessarily result in trade between the province and the capital requiring &ldquo;a long overland journey.&rdquo; Choice C is incorrect because to say that Xoconochco&rsquo;s location within the Aztec Empire was &ldquo;approximate&rdquo; would mean that the location either wasn&rsquo;t precisely correct or was close to some other location. Neither of these meanings would make sense in context because the text indicates that Xoconochco&rsquo;s location is known and that it was far from the empire&rsquo;s capital, so there&rsquo;s no reason to characterize the location as either not precisely correct or close to another location. </p>","parenttemplatename":"OSP-945-WIC","parenttemplateid":"","templateclusterid":"6144c2d2-6f14-42c6-a9c4-6371964209d5","templateclustername":"","origin":"proteus","position":"0","createDate":1691007959356,"updateDate":1691007959356}$SATQ$::jsonb, 1691007959356, 1691007959356),
    ($SATQ$a7991da1$SATQ$, $SATQ$f8b434fb-6251-45d0-bce9-7473565978b3$SATQ$::uuid, NULL, NULL, $SATQ$qbank$SATQ$, $SATQ$SAT$SATQ$, 1, $SATQ$Reading and Writing$SATQ$, $SATQ$Craft and Structure$SATQ$, $SATQ$CAS$SATQ$, $SATQ$WIC$SATQ$, $SATQ$Words in Context$SATQ$, $SATQ$E$SATQ$, 3, $SATQ$mcq$SATQ$, $SATQ$<p>A unique dialect, or regional variety, of Spanish is spoken in Puerto Rico. It contains many words borrowed from the language of the Ta&iacute;nos, the Indigenous people of Puerto Rico. African languages also made important contributions to the Puerto Rican dialect. For example, the way certain vowel sounds are pronounced in it can be <span aria-hidden="true">______</span><span class="sr-only">blank</span> to how they are pronounced in Yoruba, a West African language.</p>$SATQ$, $SATQ$<p>Which choice completes the text with the most logical and precise word or phrase?</p>$SATQ$, $SATQ$[{"id":"41ec7c50-8310-4b4d-8030-b85b415a9dbd","content":"<p>traced</p>"},{"id":"b3e08dfa-50ac-440d-8e3f-327450ed5a71","content":"<p>surrendered</p>"},{"id":"93f48f59-1705-4de0-b98a-ce8812fa6e76","content":"<p>announced</p>"},{"id":"ee07602a-aedd-45d4-ac2f-57115f95ec1e","content":"<p>offered</p>"}]$SATQ$::jsonb, $SATQ$["A"]$SATQ$::jsonb, $SATQ$["41ec7c50-8310-4b4d-8030-b85b415a9dbd"]$SATQ$::jsonb, $SATQ$<p>Choice A is the best answer because it most logically completes the text&rsquo;s discussion of the origins of the unique dialect of Spanish spoken in Puerto Rico. In this context, "traced" means tracked back to. The text notes that the regional variety of Spanish spoken in Puerto Rico has its roots in the language of the Ta&iacute;nos and in the West African language of Yoruba. This context supports the idea that the way certain vowel sounds are pronounced in the Puerto Rican dialect can be traced back to Yoruba.</p><p>Choice B is incorrect because the text presents the statement about the relationship between vowel pronunciation in the Puerto Rican dialect of Spanish and in Yoruba as an example to support the claim that African languages have contributed to the Puerto Rican dialect. It therefore wouldn&rsquo;t make sense to say that the pronunciation of certain vowel sounds in the Puerto Rican dialect can be "surrendered," or handed over on demand, to the pronunciation in Yoruba. Choice C is incorrect because the text gives no indication that the way certain vowel sounds are pronounced in the Puerto Rican dialect of Spanish has been "announced," or officially declared or proclaimed. According to the text, elements of the dialect have been inherited or borrowed from African languages, and the relationship between the pronunciation of certain vowels in the Puerto Rican dialect and in Yoruba is an example of this inheritance, suggesting that the pronunciation in the Puerto Rican dialect can be traced to Yoruba. Choice D is incorrect because the text presents the statement about the relationship between vowel pronunciation in the Puerto Rican dialect of Spanish and in Yoruba as an example to support the claim that African languages have contributed to the Puerto Rican dialect. It therefore wouldn&rsquo;t make sense to say that the pronunciation of certain vowel sounds in the Puerto Rican dialect can be "offered," or presented as a gift, to the pronunciation in Yoruba.</p>$SATQ$, false, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, $SATQ${"questionId":"a7991da1","external_id":"f8b434fb-6251-45d0-bce9-7473565978b3","vaultid":null,"uId":"b4fa7f9c-6ea9-454f-b8b2-0c9ed6cea6f9","program":"SAT","test_type":1,"test_type_desc":"Reading and Writing","primary_class_cd":"CAS","domain":"Craft and Structure","skill_cd":"WIC","skill_desc":"Words in Context","difficulty":"E","score_band_range_cd":3,"type":"mcq","stimulus":"<p>A unique dialect, or regional variety, of Spanish is spoken in Puerto Rico. It contains many words borrowed from the language of the Ta&iacute;nos, the Indigenous people of Puerto Rico. African languages also made important contributions to the Puerto Rican dialect. For example, the way certain vowel sounds are pronounced in it can be <span aria-hidden=\"true\">______</span><span class=\"sr-only\">blank</span> to how they are pronounced in Yoruba, a West African language.</p>","stem":"<p>Which choice completes the text with the most logical and precise word or phrase?</p>","answerOptions":[{"id":"41ec7c50-8310-4b4d-8030-b85b415a9dbd","content":"<p>traced</p>"},{"id":"b3e08dfa-50ac-440d-8e3f-327450ed5a71","content":"<p>surrendered</p>"},{"id":"93f48f59-1705-4de0-b98a-ce8812fa6e76","content":"<p>announced</p>"},{"id":"ee07602a-aedd-45d4-ac2f-57115f95ec1e","content":"<p>offered</p>"}],"keys":["41ec7c50-8310-4b4d-8030-b85b415a9dbd"],"correct_answer":["A"],"rationale":"<p>Choice A is the best answer because it most logically completes the text&rsquo;s discussion of the origins of the unique dialect of Spanish spoken in Puerto Rico. In this context, \"traced\" means tracked back to. The text notes that the regional variety of Spanish spoken in Puerto Rico has its roots in the language of the Ta&iacute;nos and in the West African language of Yoruba. This context supports the idea that the way certain vowel sounds are pronounced in the Puerto Rican dialect can be traced back to Yoruba.</p><p>Choice B is incorrect because the text presents the statement about the relationship between vowel pronunciation in the Puerto Rican dialect of Spanish and in Yoruba as an example to support the claim that African languages have contributed to the Puerto Rican dialect. It therefore wouldn&rsquo;t make sense to say that the pronunciation of certain vowel sounds in the Puerto Rican dialect can be \"surrendered,\" or handed over on demand, to the pronunciation in Yoruba. Choice C is incorrect because the text gives no indication that the way certain vowel sounds are pronounced in the Puerto Rican dialect of Spanish has been \"announced,\" or officially declared or proclaimed. According to the text, elements of the dialect have been inherited or borrowed from African languages, and the relationship between the pronunciation of certain vowels in the Puerto Rican dialect and in Yoruba is an example of this inheritance, suggesting that the pronunciation in the Puerto Rican dialect can be traced to Yoruba. Choice D is incorrect because the text presents the statement about the relationship between vowel pronunciation in the Puerto Rican dialect of Spanish and in Yoruba as an example to support the claim that African languages have contributed to the Puerto Rican dialect. It therefore wouldn&rsquo;t make sense to say that the pronunciation of certain vowel sounds in the Puerto Rican dialect can be \"offered,\" or presented as a gift, to the pronunciation in Yoruba.</p>","parenttemplatename":null,"parenttemplateid":null,"templateclusterid":null,"templateclustername":null,"origin":null,"position":null,"createDate":1730147323041,"updateDate":1730147323041}$SATQ$::jsonb, 1730147323041, 1730147323041),
    ($SATQ$a87c3925$SATQ$, $SATQ$7c99a73d-836b-4ef9-82aa-79f1b2805261$SATQ$::uuid, $SATQ$d4c9ca0c-c5de-456c-8cab-a17cfcee3acd$SATQ$::uuid, NULL, $SATQ$qbank$SATQ$, $SATQ$SAT$SATQ$, 1, $SATQ$Reading and Writing$SATQ$, $SATQ$Craft and Structure$SATQ$, $SATQ$CAS$SATQ$, $SATQ$CTC$SATQ$, $SATQ$Cross-Text Connections$SATQ$, $SATQ$H$SATQ$, 7, $SATQ$mcq$SATQ$, $SATQ$<p><strong><span role="heading" aria-level="2">Text 1</span></strong></p>
<p>Soy sauce, made from fermented soybeans, is noted for its umami flavor. Umami&mdash;one of the five basic tastes along with sweet, bitter, salty, and sour&mdash;was formally classified when its taste receptors were discovered in the 2000s. In 2007, to define the pure umami flavor scientists Rie Ishii and Michael O&rsquo;Mahony used broths made from shiitake mushrooms and kombu seaweed, and two panels of Japanese and US judges closely agreed on a description of the taste.</p>
<p>&nbsp;</p>
<p><strong><span role="heading" aria-level="2">Text 2</span></strong></p>
<p>A 2022 experiment by Manon J&uuml;nger et al. led to a greater understanding of soy sauce&rsquo;s flavor profile. The team initially presented a mixture of compounds with low molecular weights to taste testers who found it was not as salty or bitter as real soy sauce. Further analysis of soy sauce identified proteins, including dipeptides, that enhanced umami flavor and also contributed to saltiness. The team then made a mix of 50 chemical compounds that re-created soy sauce&rsquo;s flavor.</p>$SATQ$, $SATQ$<p>Based on the texts, if Ishii and O&rsquo;Mahony (Text 1) and J&uuml;nger et al. (Text 2) were aware of the findings of both experiments, they would most likely agree with which statement?</p>$SATQ$, $SATQ$[{"id":"0dcfb41c-9ce7-4f87-8000-e5e3ecd91770","content":"<p>On average, the diets of people in the United States tend to have fewer foods that contain certain dipeptides than the diets of people in Japan have.</p>"},{"id":"938e3518-aae5-4c0b-81ba-9a39c9674df4","content":"<p>Chemical compounds that activate both the umami and salty taste receptors tend to have a higher molecular weight than those that only activate umami taste receptors.</p>"},{"id":"101d5415-16b8-4dd7-992c-c1df19b5659f","content":"<p>Fermentation introduces proteins responsible for the increase of umami flavor in soy sauce, and those proteins also increase the perception of saltiness.</p>"},{"id":"83262271-f126-4f7c-b763-59c880ee2b5f","content":"<p>The broths in the 2007 experiment most likely did not have a substantial amount of the dipeptides that played a key part in the 2022 experiment.</p>"}]$SATQ$::jsonb, $SATQ$["D"]$SATQ$::jsonb, $SATQ$["83262271-f126-4f7c-b763-59c880ee2b5f"]$SATQ$::jsonb, $SATQ$<p>Choice D is the best answer. Ishii and O&rsquo;Mahony were trying to isolate the pure umami flavor, while J&uuml;nger was trying to recreate soy sauce, which has a mix of flavors that includes umami. Accordingly, the broths from Text 1 are not described as having any soy sauce in them&mdash;just &ldquo;shiitake mushrooms and kombu seaweed.&rdquo; So they probably don&rsquo;t have as much of the dipeptides described in Text 2, which were found to be a key part of soy sauce&rsquo;s umami-ness and its saltiness. </p><p>Choice A is incorrect. Neither text supports this. Neither text gets into the diets of people in the United States, nor the diets of people in Japan. Choice B is incorrect. Neither text supports this. Text 2 does talk about the molecular weights of chemical compounds, but there isn&rsquo;t enough information provided about molecular weights in Text 1 to make an inference about what the scientists in Text 1 would say. Choice C is incorrect. Neither text supports this. Text 1 briefly mentions that soy sauce is &ldquo;made from fermented soybeans,&rdquo; but it never claims that fermentation is responsible for its flavor in any way. And Text 2 never mentions fermentation at all. </p>$SATQ$, false, 0, $SATQ$OSP-KA-CTC-H004$SATQ$, $SATQ$$SATQ$, $SATQ$86fe0dd5-29ce-4501-bb68-96cd470ad616$SATQ$::uuid, $SATQ$$SATQ$, $SATQ$proteus$SATQ$, $SATQ$0$SATQ$, NULL, NULL, $SATQ${"questionId":"a87c3925","external_id":"7c99a73d-836b-4ef9-82aa-79f1b2805261","vaultid":"d4c9ca0c-c5de-456c-8cab-a17cfcee3acd","uId":"23bac07a-b650-4ac3-8d4a-d0645b4d7300","program":"SAT","test_type":1,"test_type_desc":"Reading and Writing","primary_class_cd":"CAS","domain":"Craft and Structure","skill_cd":"CTC","skill_desc":"Cross-Text Connections","difficulty":"H","score_band_range_cd":7,"type":"mcq","stimulus":"<p><strong><span role=\"heading\" aria-level=\"2\">Text 1</span></strong></p>\n<p>Soy sauce, made from fermented soybeans, is noted for its umami flavor. Umami&mdash;one of the five basic tastes along with sweet, bitter, salty, and sour&mdash;was formally classified when its taste receptors were discovered in the 2000s. In 2007, to define the pure umami flavor scientists Rie Ishii and Michael O&rsquo;Mahony used broths made from shiitake mushrooms and kombu seaweed, and two panels of Japanese and US judges closely agreed on a description of the taste.</p>\n<p>&nbsp;</p>\n<p><strong><span role=\"heading\" aria-level=\"2\">Text 2</span></strong></p>\n<p>A 2022 experiment by Manon J&uuml;nger et al. led to a greater understanding of soy sauce&rsquo;s flavor profile. The team initially presented a mixture of compounds with low molecular weights to taste testers who found it was not as salty or bitter as real soy sauce. Further analysis of soy sauce identified proteins, including dipeptides, that enhanced umami flavor and also contributed to saltiness. The team then made a mix of 50 chemical compounds that re-created soy sauce&rsquo;s flavor.</p>","stem":"<p>Based on the texts, if Ishii and O&rsquo;Mahony (Text 1) and J&uuml;nger et al. (Text 2) were aware of the findings of both experiments, they would most likely agree with which statement?</p>","answerOptions":[{"id":"0dcfb41c-9ce7-4f87-8000-e5e3ecd91770","content":"<p>On average, the diets of people in the United States tend to have fewer foods that contain certain dipeptides than the diets of people in Japan have.</p>"},{"id":"938e3518-aae5-4c0b-81ba-9a39c9674df4","content":"<p>Chemical compounds that activate both the umami and salty taste receptors tend to have a higher molecular weight than those that only activate umami taste receptors.</p>"},{"id":"101d5415-16b8-4dd7-992c-c1df19b5659f","content":"<p>Fermentation introduces proteins responsible for the increase of umami flavor in soy sauce, and those proteins also increase the perception of saltiness.</p>"},{"id":"83262271-f126-4f7c-b763-59c880ee2b5f","content":"<p>The broths in the 2007 experiment most likely did not have a substantial amount of the dipeptides that played a key part in the 2022 experiment.</p>"}],"keys":["83262271-f126-4f7c-b763-59c880ee2b5f"],"correct_answer":["D"],"rationale":"<p>Choice D is the best answer. Ishii and O&rsquo;Mahony were trying to isolate the pure umami flavor, while J&uuml;nger was trying to recreate soy sauce, which has a mix of flavors that includes umami. Accordingly, the broths from Text 1 are not described as having any soy sauce in them&mdash;just &ldquo;shiitake mushrooms and kombu seaweed.&rdquo; So they probably don&rsquo;t have as much of the dipeptides described in Text 2, which were found to be a key part of soy sauce&rsquo;s umami-ness and its saltiness. </p><p>Choice A is incorrect. Neither text supports this. Neither text gets into the diets of people in the United States, nor the diets of people in Japan. Choice B is incorrect. Neither text supports this. Text 2 does talk about the molecular weights of chemical compounds, but there isn&rsquo;t enough information provided about molecular weights in Text 1 to make an inference about what the scientists in Text 1 would say. Choice C is incorrect. Neither text supports this. Text 1 briefly mentions that soy sauce is &ldquo;made from fermented soybeans,&rdquo; but it never claims that fermentation is responsible for its flavor in any way. And Text 2 never mentions fermentation at all. </p>","parenttemplatename":"OSP-KA-CTC-H004","parenttemplateid":"","templateclusterid":"86fe0dd5-29ce-4501-bb68-96cd470ad616","templateclustername":"","origin":"proteus","position":"0","createDate":1691007959365,"updateDate":1691007959365}$SATQ$::jsonb, 1691007959365, 1691007959365),
    ($SATQ$aa5897b8$SATQ$, $SATQ$0bfc085a-d882-418f-a208-100aefcda7fa$SATQ$::uuid, $SATQ$83dcd9d4-ee1c-4885-9c51-7a85ec35e0aa$SATQ$::uuid, NULL, $SATQ$qbank$SATQ$, $SATQ$SAT$SATQ$, 1, $SATQ$Reading and Writing$SATQ$, $SATQ$Craft and Structure$SATQ$, $SATQ$CAS$SATQ$, $SATQ$TSP$SATQ$, $SATQ$Text Structure and Purpose$SATQ$, $SATQ$H$SATQ$, 7, $SATQ$mcq$SATQ$, $SATQ$<p><u>In Jane Austen&rsquo;s novel <em>Mansfield Park</em>, an almost imperceptible smile from potential suitor Henry Crawford causes the protagonist Fanny Price to blush; her embarrassment grows when she suspects that he is aware of it.</u> This moment&mdash;in which Fanny not only infers Henry&rsquo;s mental state through his gestures, but also infers that <em>he</em> is drawing inferences about <em>her</em> mental state&mdash;illustrates what literary scholar George Butte calls &ldquo;deep intersubjectivity,&rdquo; a technique for representing interactions between consciousnesses through which Austen&rsquo;s novels derive much of their social and psychological drama.</p>$SATQ$, $SATQ$<p>Which choice best describes the function of the underlined sentence in the text as a whole?</p>$SATQ$, $SATQ$[{"id":"56d13b85-f6b0-432a-b5c4-666355b17a1d","content":"<p>It states a claim about Austen&rsquo;s skill at representing psychological complexity that is reinforced by an example presented in the following sentence.&nbsp;</p>"},{"id":"a1a96748-3b8f-4a27-8df3-44882cd7ec1e","content":"<p>It advances an interpretation of an Austen protagonist who is contrasted with protagonists from other Austen novels cited in the following sentence.&nbsp;</p>"},{"id":"900310f3-3a00-4b67-bf77-b6b1831a4ec3","content":"<p>It describes a recurring theme in Austen&rsquo;s novels that is the focus of a literary scholar&rsquo;s analysis summarized in the following sentence.&nbsp;</p>"},{"id":"12207b90-cb8d-4f82-b5ef-5d2e1f215aac","content":"<p>It provides a synopsis of an interaction in an Austen novel that illustrates a literary concept discussed in the following sentence.&nbsp;</p>"}]$SATQ$::jsonb, $SATQ$["D"]$SATQ$::jsonb, $SATQ$["12207b90-cb8d-4f82-b5ef-5d2e1f215aac"]$SATQ$::jsonb, $SATQ$<p>Choice D is the best answer. The underlined sentence provides a concrete example to ground readers&rsquo; understanding of the &ldquo;deep intersubjectivity&rdquo; described in the next sentence as central to Austen&rsquo;s work. </p><p>Choice A is incorrect. There is no evaluation made of Austen&rsquo;s skill in this sentence, and no examples are given in the following sentence. This choice essentially flips the paragraph: it&rsquo;s this first sentence that provides an example. Choice B is incorrect. There are no other Austen protagonists mentioned in this passage, so this couldn&rsquo;t be the answer. Choice C is incorrect. The underlined sentence doesn&rsquo;t identify any &ldquo;recurring theme,&rdquo; but instead simply describes one interaction from one book. This interaction exemplifies the literary technique of &ldquo;deep intersubjectivity&rdquo; that is introduced in the next sentence. </p>$SATQ$, false, 0, $SATQ$OSP-KA-TSP-H007$SATQ$, $SATQ$$SATQ$, $SATQ$c29e2b32-d75d-48cd-9b99-b1ebe4608d26$SATQ$::uuid, $SATQ$$SATQ$, $SATQ$proteus$SATQ$, $SATQ$0$SATQ$, NULL, NULL, $SATQ${"questionId":"aa5897b8","external_id":"0bfc085a-d882-418f-a208-100aefcda7fa","vaultid":"83dcd9d4-ee1c-4885-9c51-7a85ec35e0aa","uId":"3cd2b9b2-3881-44c2-9327-ad7e42ca47c5","program":"SAT","test_type":1,"test_type_desc":"Reading and Writing","primary_class_cd":"CAS","domain":"Craft and Structure","skill_cd":"TSP","skill_desc":"Text Structure and Purpose","difficulty":"H","score_band_range_cd":7,"type":"mcq","stimulus":"<p><u>In Jane Austen&rsquo;s novel <em>Mansfield Park</em>, an almost imperceptible smile from potential suitor Henry Crawford causes the protagonist Fanny Price to blush; her embarrassment grows when she suspects that he is aware of it.</u> This moment&mdash;in which Fanny not only infers Henry&rsquo;s mental state through his gestures, but also infers that <em>he</em> is drawing inferences about <em>her</em> mental state&mdash;illustrates what literary scholar George Butte calls &ldquo;deep intersubjectivity,&rdquo; a technique for representing interactions between consciousnesses through which Austen&rsquo;s novels derive much of their social and psychological drama.</p>","stem":"<p>Which choice best describes the function of the underlined sentence in the text as a whole?</p>","answerOptions":[{"id":"56d13b85-f6b0-432a-b5c4-666355b17a1d","content":"<p>It states a claim about Austen&rsquo;s skill at representing psychological complexity that is reinforced by an example presented in the following sentence.&nbsp;</p>"},{"id":"a1a96748-3b8f-4a27-8df3-44882cd7ec1e","content":"<p>It advances an interpretation of an Austen protagonist who is contrasted with protagonists from other Austen novels cited in the following sentence.&nbsp;</p>"},{"id":"900310f3-3a00-4b67-bf77-b6b1831a4ec3","content":"<p>It describes a recurring theme in Austen&rsquo;s novels that is the focus of a literary scholar&rsquo;s analysis summarized in the following sentence.&nbsp;</p>"},{"id":"12207b90-cb8d-4f82-b5ef-5d2e1f215aac","content":"<p>It provides a synopsis of an interaction in an Austen novel that illustrates a literary concept discussed in the following sentence.&nbsp;</p>"}],"keys":["12207b90-cb8d-4f82-b5ef-5d2e1f215aac"],"correct_answer":["D"],"rationale":"<p>Choice D is the best answer. The underlined sentence provides a concrete example to ground readers&rsquo; understanding of the &ldquo;deep intersubjectivity&rdquo; described in the next sentence as central to Austen&rsquo;s work. </p><p>Choice A is incorrect. There is no evaluation made of Austen&rsquo;s skill in this sentence, and no examples are given in the following sentence. This choice essentially flips the paragraph: it&rsquo;s this first sentence that provides an example. Choice B is incorrect. There are no other Austen protagonists mentioned in this passage, so this couldn&rsquo;t be the answer. Choice C is incorrect. The underlined sentence doesn&rsquo;t identify any &ldquo;recurring theme,&rdquo; but instead simply describes one interaction from one book. This interaction exemplifies the literary technique of &ldquo;deep intersubjectivity&rdquo; that is introduced in the next sentence. </p>","parenttemplatename":"OSP-KA-TSP-H007","parenttemplateid":"","templateclusterid":"c29e2b32-d75d-48cd-9b99-b1ebe4608d26","templateclustername":"","origin":"proteus","position":"0","createDate":1691007959375,"updateDate":1691007959375}$SATQ$::jsonb, 1691007959375, 1691007959375),
    ($SATQ$aa7ae735$SATQ$, $SATQ$d1cf2aa4-3cbd-4fee-b186-c241183fc074$SATQ$::uuid, $SATQ$6f1e83ff-488e-4eb2-a595-dc8d5575dc95$SATQ$::uuid, NULL, $SATQ$qbank$SATQ$, $SATQ$SAT$SATQ$, 1, $SATQ$Reading and Writing$SATQ$, $SATQ$Craft and Structure$SATQ$, $SATQ$CAS$SATQ$, $SATQ$WIC$SATQ$, $SATQ$Words in Context$SATQ$, $SATQ$E$SATQ$, 3, $SATQ$mcq$SATQ$, $SATQ$<p>The following text is adapted from Mohsin Hamid&rsquo;s 2017 novel <em>Exit West</em>. Saeed lives with his mother and father.</p>
<p>On cloudless nights after a daytime rain, Saeed&rsquo;s father would sometimes bring out the telescope, and the family would sip green tea on their balcony, enjoying a breeze, and take turns to look up at objects whose light, often, had been emitted before any of these three viewers had been born&mdash;light from other centuries, only now <u>reaching</u> Earth.</p>
<p>&copy;2017 by Mohsin Hamid</p>$SATQ$, $SATQ$<p>As used in the text, what does the word &ldquo;reaching&rdquo; most nearly mean?</p>$SATQ$, $SATQ$[{"id":"60b70d22-9fc0-4eaa-89c8-d4c9e94c1324","content":"<p>Arriving at</p>"},{"id":"682d8bf2-9b26-4ed0-9233-5a7ad720ebab","content":"<p>Consulting with</p>"},{"id":"2b99c944-5bad-44fe-95d1-171fed87af9e","content":"<p>Running to</p>"},{"id":"48878efc-7469-47a8-a272-8a20a99b0634","content":"<p>Clinging to</p>"}]$SATQ$::jsonb, $SATQ$["A"]$SATQ$::jsonb, $SATQ$["60b70d22-9fc0-4eaa-89c8-d4c9e94c1324"]$SATQ$::jsonb, $SATQ$<p>Choice A is the best answer. The word "reaching" in this text means "to arrive" at Earth. Before, the light had been traveling across space; now, it had arrived at Earth.</p><p>Choice B is incorrect. "Consulting with" means "seeking advice or information from someone." Light is not alive, so it can&rsquo;t consult with Earth. Choice C is incorrect. It&rsquo;s confusing to say that starlight is "only now running to Earth," both because light doesn&rsquo;t literally "run" and because the text is describing the moment the light touches Earth, not the period of time when it&rsquo;s traveling to Earth. Choice D is incorrect. This might be tempting, as "clinging to" has a connotation of "sticking to." It wouldn&rsquo;t make sense to say that the light was "only now" clinging to Earth.</p>$SATQ$, false, 0, $SATQ$OSP-KA-WIC-M005$SATQ$, $SATQ$$SATQ$, $SATQ$0481745f-d466-41fb-8966-a87d8c017da7$SATQ$::uuid, $SATQ$$SATQ$, $SATQ$proteus$SATQ$, $SATQ$0$SATQ$, NULL, NULL, $SATQ${"questionId":"aa7ae735","external_id":"d1cf2aa4-3cbd-4fee-b186-c241183fc074","vaultid":"6f1e83ff-488e-4eb2-a595-dc8d5575dc95","uId":"b3daf4c8-f5d3-421a-b78f-f6cc22b5a538","program":"SAT","test_type":1,"test_type_desc":"Reading and Writing","primary_class_cd":"CAS","domain":"Craft and Structure","skill_cd":"WIC","skill_desc":"Words in Context","difficulty":"E","score_band_range_cd":3,"type":"mcq","stimulus":"<p>The following text is adapted from Mohsin Hamid&rsquo;s 2017 novel <em>Exit West</em>. Saeed lives with his mother and father.</p>\n<p>On cloudless nights after a daytime rain, Saeed&rsquo;s father would sometimes bring out the telescope, and the family would sip green tea on their balcony, enjoying a breeze, and take turns to look up at objects whose light, often, had been emitted before any of these three viewers had been born&mdash;light from other centuries, only now <u>reaching</u> Earth.</p>\n<p>&copy;2017 by Mohsin Hamid</p>","stem":"<p>As used in the text, what does the word &ldquo;reaching&rdquo; most nearly mean?</p>","answerOptions":[{"id":"60b70d22-9fc0-4eaa-89c8-d4c9e94c1324","content":"<p>Arriving at</p>"},{"id":"682d8bf2-9b26-4ed0-9233-5a7ad720ebab","content":"<p>Consulting with</p>"},{"id":"2b99c944-5bad-44fe-95d1-171fed87af9e","content":"<p>Running to</p>"},{"id":"48878efc-7469-47a8-a272-8a20a99b0634","content":"<p>Clinging to</p>"}],"keys":["60b70d22-9fc0-4eaa-89c8-d4c9e94c1324"],"correct_answer":["A"],"rationale":"<p>Choice A is the best answer. The word \"reaching\" in this text means \"to arrive\" at Earth. Before, the light had been traveling across space; now, it had arrived at Earth.</p><p>Choice B is incorrect. \"Consulting with\" means \"seeking advice or information from someone.\" Light is not alive, so it can&rsquo;t consult with Earth. Choice C is incorrect. It&rsquo;s confusing to say that starlight is \"only now running to Earth,\" both because light doesn&rsquo;t literally \"run\" and because the text is describing the moment the light touches Earth, not the period of time when it&rsquo;s traveling to Earth. Choice D is incorrect. This might be tempting, as \"clinging to\" has a connotation of \"sticking to.\" It wouldn&rsquo;t make sense to say that the light was \"only now\" clinging to Earth.</p>","parenttemplatename":"OSP-KA-WIC-M005","parenttemplateid":"","templateclusterid":"0481745f-d466-41fb-8966-a87d8c017da7","templateclustername":"","origin":"proteus","position":"0","createDate":1691007959378,"updateDate":1691007959378}$SATQ$::jsonb, 1691007959378, 1691007959378),
    ($SATQ$aa7fc89b$SATQ$, $SATQ$44563440-0571-499d-ba56-db50174dd26b$SATQ$::uuid, $SATQ$f54aba88-a597-4059-90d0-e76111ef44fe$SATQ$::uuid, NULL, $SATQ$qbank$SATQ$, $SATQ$SAT$SATQ$, 1, $SATQ$Reading and Writing$SATQ$, $SATQ$Craft and Structure$SATQ$, $SATQ$CAS$SATQ$, $SATQ$TSP$SATQ$, $SATQ$Text Structure and Purpose$SATQ$, $SATQ$M$SATQ$, 4, $SATQ$mcq$SATQ$, $SATQ$<p>The following text is adapted from Susan Glaspell&rsquo;s 1912 short story &ldquo;&lsquo;Out There.&rsquo;&rdquo; An elderly shop owner is looking at a picture that he recently acquired and hopes to sell.</p>
<p style='padding-left: 1em;'>It did seem that the picture failed to fit in with the rest of the shop. A persuasive young fellow who claimed he was closing out his stock let the old man have it for what he called a song. It was only a little out-of-the-way store which subsisted chiefly on the framing of pictures. The old man looked around at his views of the city, his pictures of cats and dogs, his flaming bits of landscape. &ldquo;Don&rsquo;t belong in here,&rdquo; he fumed.</p>
<p style='padding-left: 1em;'>And yet the old man was secretly proud of his acquisition. There was a hidden dignity in his scowling as he shuffled about pondering the least ridiculous place for the picture.</p>$SATQ$, $SATQ$<p>Which choice best states the main purpose of the text?</p>$SATQ$, $SATQ$[{"id":"413b29c5-6597-41e3-ab4b-ef224aa2fe17","content":"<p>To reveal the shop owner&rsquo;s conflicted feelings about the new picture</p>"},{"id":"1936f5a1-6832-49d4-bf3f-28468fe689db","content":"<p>To convey the shop owner&rsquo;s resentment of the person he got the new picture from</p>"},{"id":"3ae1456e-c791-4adc-b989-7538bda7506b","content":"<p>To describe the items that the shop owner most highly prizes</p>"},{"id":"f4e5b3dc-e4a8-4ec0-a682-40017551abc6","content":"<p>To explain differences between the new picture and other pictures in the shop</p>"}]$SATQ$::jsonb, $SATQ$["A"]$SATQ$::jsonb, $SATQ$["413b29c5-6597-41e3-ab4b-ef224aa2fe17"]$SATQ$::jsonb, $SATQ$<p>Choice A is the best answer because it most accurately describes the main purpose of the text. The text begins by stating that the new picture &ldquo;failed to fit in&rdquo; with the other items that the shop owner has. The text goes on to illustrate that point by describing the other pictures the shop owner has, indicating that the shop owner is fuming because he doesn&rsquo;t think the new picture belongs in the store. In the second paragraph, however, the text indicates that the shop owner is &ldquo;secretly proud of his acquisition.&rdquo; The main purpose of the text is thus to reveal the shop owner&rsquo;s conflicted feelings about the new picture. </p><p>Choice B is incorrect because the text doesn&rsquo;t suggest that the shop owner resents the young man who sold him the new picture; in fact, the text gives no indication of the owner&rsquo;s feelings about the young man at all. Choice C is incorrect. Although the text indicates that the new picture is different from the other items in the shop, there&rsquo;s no suggestion that the shop owner prizes either the new picture or the pictures of the city, pets, and landscapes more than he prizes any other items. Choice D is incorrect because the text doesn&rsquo;t describe what the new picture looks like; rather, the text identifies some of the other kinds of images that the shop owner has and states that they&rsquo;re different from the new picture without explaining how they&rsquo;re different.&nbsp;</p>$SATQ$, false, 0, $SATQ$OSP-036-TSP$SATQ$, $SATQ$$SATQ$, $SATQ$9b7983fc-7df4-4c53-b3a3-1bd0e1de22b7$SATQ$::uuid, $SATQ$$SATQ$, $SATQ$proteus$SATQ$, $SATQ$0$SATQ$, NULL, NULL, $SATQ${"questionId":"aa7fc89b","external_id":"44563440-0571-499d-ba56-db50174dd26b","vaultid":"f54aba88-a597-4059-90d0-e76111ef44fe","uId":"dafd5a78-106e-4ee5-86f5-b1cbf3ff7649","program":"SAT","test_type":1,"test_type_desc":"Reading and Writing","primary_class_cd":"CAS","domain":"Craft and Structure","skill_cd":"TSP","skill_desc":"Text Structure and Purpose","difficulty":"M","score_band_range_cd":4,"type":"mcq","stimulus":"<p>The following text is adapted from Susan Glaspell&rsquo;s 1912 short story &ldquo;&lsquo;Out There.&rsquo;&rdquo; An elderly shop owner is looking at a picture that he recently acquired and hopes to sell.</p>\n<p style='padding-left: 1em;'>It did seem that the picture failed to fit in with the rest of the shop. A persuasive young fellow who claimed he was closing out his stock let the old man have it for what he called a song. It was only a little out-of-the-way store which subsisted chiefly on the framing of pictures. The old man looked around at his views of the city, his pictures of cats and dogs, his flaming bits of landscape. &ldquo;Don&rsquo;t belong in here,&rdquo; he fumed.</p>\n<p style='padding-left: 1em;'>And yet the old man was secretly proud of his acquisition. There was a hidden dignity in his scowling as he shuffled about pondering the least ridiculous place for the picture.</p>","stem":"<p>Which choice best states the main purpose of the text?</p>","answerOptions":[{"id":"413b29c5-6597-41e3-ab4b-ef224aa2fe17","content":"<p>To reveal the shop owner&rsquo;s conflicted feelings about the new picture</p>"},{"id":"1936f5a1-6832-49d4-bf3f-28468fe689db","content":"<p>To convey the shop owner&rsquo;s resentment of the person he got the new picture from</p>"},{"id":"3ae1456e-c791-4adc-b989-7538bda7506b","content":"<p>To describe the items that the shop owner most highly prizes</p>"},{"id":"f4e5b3dc-e4a8-4ec0-a682-40017551abc6","content":"<p>To explain differences between the new picture and other pictures in the shop</p>"}],"keys":["413b29c5-6597-41e3-ab4b-ef224aa2fe17"],"correct_answer":["A"],"rationale":"<p>Choice A is the best answer because it most accurately describes the main purpose of the text. The text begins by stating that the new picture &ldquo;failed to fit in&rdquo; with the other items that the shop owner has. The text goes on to illustrate that point by describing the other pictures the shop owner has, indicating that the shop owner is fuming because he doesn&rsquo;t think the new picture belongs in the store. In the second paragraph, however, the text indicates that the shop owner is &ldquo;secretly proud of his acquisition.&rdquo; The main purpose of the text is thus to reveal the shop owner&rsquo;s conflicted feelings about the new picture. </p><p>Choice B is incorrect because the text doesn&rsquo;t suggest that the shop owner resents the young man who sold him the new picture; in fact, the text gives no indication of the owner&rsquo;s feelings about the young man at all. Choice C is incorrect. Although the text indicates that the new picture is different from the other items in the shop, there&rsquo;s no suggestion that the shop owner prizes either the new picture or the pictures of the city, pets, and landscapes more than he prizes any other items. Choice D is incorrect because the text doesn&rsquo;t describe what the new picture looks like; rather, the text identifies some of the other kinds of images that the shop owner has and states that they&rsquo;re different from the new picture without explaining how they&rsquo;re different.&nbsp;</p>","parenttemplatename":"OSP-036-TSP","parenttemplateid":"","templateclusterid":"9b7983fc-7df4-4c53-b3a3-1bd0e1de22b7","templateclustername":"","origin":"proteus","position":"0","createDate":1691007959320,"updateDate":1691007959320}$SATQ$::jsonb, 1691007959320, 1691007959320)
